// Copyright lowRISC contributors.
// Copyright 2018 ETH Zurich and University of Bologna, see also CREDITS.md.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

package ibex_pkg;

  localparam int PMP_MAX_REGIONS = 16;
  localparam int PMP_ADDR_W = 34;
  localparam int PMP_ADDR_MSB = PMP_ADDR_W - 1;

  localparam int PMP_I  = 0;
  localparam int PMP_I2 = 1;
  localparam int PMP_D  = 2;

  localparam int BUS_SIZE = 32;

  localparam int IC_NUM_WAYS = 2;
  localparam int IC_LINE_SIZE = 64;
  localparam int IC_TAG_SIZE = 22;
  localparam int IC_INDEX_W = 6;

  localparam int PMP_CFG_W = 8;

  typedef enum logic [1:0] {
    PRIV_LVL_M = 2'b11,
    PRIV_LVL_H = 2'b10,
    PRIV_LVL_S = 2'b01,
    PRIV_LVL_U = 2'b00
  } priv_lvl_e;

  typedef enum logic [1:0] {
    RV32MNone        = 2'b00,
    RV32MSlow        = 2'b01,
    RV32MFast        = 2'b10,
    RV32MSingleCycle = 2'b11
  } rv32m_e;

  typedef enum logic [1:0] {
    RV32BNone       = 2'b00,
    RV32BBalanced   = 2'b01,
    RV32BOTEarlGrey = 2'b10,
    RV32BFull       = 2'b11
  } rv32b_e;

  typedef enum logic [1:0] {
    RV32ZcNone      = 2'b00,
    RV32Zca         = 2'b01,
    RV32ZcaZcb      = 2'b10,
    RV32ZcaZcbZcmp  = 2'b11
  } rv32zc_e;

  typedef enum logic [1:0] {
    RegFileFF    = 2'b00,
    RegFileFPGA  = 2'b01,
    RegFileLatch = 2'b10
  } regfile_e;

  typedef struct packed {
    logic l;
    logic a;
  } pmp_cfg_t;

  typedef struct packed {
    logic r;
    logic w;
    logic x;
  } pmp_cfg_perm_t;

  typedef struct packed {
    logic lock;
    logic [1:0] mode;
    pmp_cfg_perm_t perm;
  } pmp_cfg_full_t;

  typedef struct packed {
    logic rlb;
    logic mmwp;
    mml_e mml;
  } pmp_mseccfg_t;

  typedef enum logic {
    MML_NONE = 1'b0,
    MML_SET  = 1'b1
  } mml_e;

  typedef enum logic [1:0] {
    PMP_ACC_EXEC  = 2'b00,
    PMP_ACC_WRITE = 2'b01,
    PMP_ACC_READ  = 2'b10
  } pmp_req_e;

  typedef enum logic [3:0] {
    ALU_ADD,
    ALU_SUB,
    ALU_XOR,
    ALU_OR,
    ALU_AND,
    ALU_SRA,
    ALU_SRL,
    ALU_SLL,
    ALU_LT,
    ALU_LTU,
    ALU_GE,
    ALU_GEU,
    ALU_EQ,
    ALU_NE,
    ALU_SLT,
    ALU_SLTU
  } alu_op_e;

  typedef enum logic [2:0] {
    MD_OP_MULL,
    MD_OP_MULH,
    MD_OP_MULHsu,
    MD_OP_MULHU,
    MD_OP_DIV,
    MD_OP_DIVU,
    MD_OP_REM,
    MD_OP_REMU
  } md_op_e;

  typedef enum logic [2:0] {
    PC_BOOT,
    PC_JUMP,
    PC_EXC,
    PC_ERET,
    PC_DRET
  } pc_sel_e;

  typedef enum logic [2:0] {
    EXC_PC_EXC,
    EXC_PC_IRQ,
    EXC_PC_DBD,
    EXC_PC_DBG_EXC,
    EXC_PC_DBG_TVA
  } exc_pc_sel_e;

  typedef enum logic [1:0] {
    CSR_OP_READ,
    CSR_OP_WRITE,
    CSR_OP_SET,
    CSR_OP_CLEAR
  } csr_op_e;

  typedef struct packed {
    logic       irq_software;
    logic       irq_timer;
    logic       irq_external;
    logic [14:0] irq_fast;
  } irqs_t;

  typedef enum logic [4:0] {
    EXC_CAUSE_IRQ_SOFTWARE_M     = 5'h03,
    EXC_CAUSE_IRQ_TIMER_M        = 5'h07,
    EXC_CAUSE_IRQ_EXTERNAL_M     = 5'h0B,
    EXC_CAUSE_IRQ_FAST_0         = 5'h10,
    EXC_CAUSE_IRQ_FAST_14        = 5'h1E,
    EXC_CAUSE_INSN_ADDR_MISA     = 5'h01,
    EXC_CAUSE_INSN_ACCESS        = 5'h02,
    EXC_CAUSE_ILLEGAL_INSN       = 5'h02,
    EXC_CAUSE_BREAKPOINT         = 5'h03,
    EXC_CAUSE_LOAD_ACCESS        = 5'h05,
    EXC_CAUSE_STORE_ACCESS       = 5'h07,
    EXC_CAUSE_ECALL_MMODE        = 5'h0B,
    EXC_CAUSE_ECALL_UMODE        = 5'h08
  } exc_cause_e;

  typedef struct packed {
    logic [31:0] current_pc;
    logic [31:0] next_pc;
    logic [31:0] last_data_addr;
    logic [31:0] exception_pc;
    logic [31:0] exception_addr;
  } crash_dump_t;

  typedef logic [3:0] ibex_mubi_t;
  localparam ibex_mubi_t IbexMuBiOn  = 4'b1010;
  localparam ibex_mubi_t IbexMuBiOff = 4'b0101;

  typedef logic [31:0] lfsr_seed_t;
  typedef logic [31:0] lfsr_perm_t;

  localparam lfsr_seed_t RndCnstLfsrSeedDefault = 32'hdeadbeef;
  localparam lfsr_perm_t RndCnstLfsrPermDefault = 32'hffffffff;

  typedef enum logic [1:0] {
    INSTR_NOT_EXPANDED,
    INSTR_EXPANDED_FIRST,
    INSTR_EXPANDED_LAST
  } instr_exp_e;

  typedef enum logic [1:0] {
    WB_INSTR_OTHER,
    WB_INSTR_BRANCH,
    WB_INSTR_MULT,
    WB_INSTR_LOAD,
    WB_INSTR_STORE
  } wb_instr_type_e;

  typedef enum logic [2:0] {
    DBG_CAUSE_NONE    = 3'h0,
    DBG_CAUSE_SWCORE  = 3'h1,
    DBG_CAUSE_TRIGGER = 3'h2,
    DBG_CAUSE_EBREAK  = 3'h3,
    DBG_CAUSE_HALTREQ = 3'h4,
    DBG_CAUSE_STEP    = 3'h5
  } dbg_cause_e;

  localparam logic [1:0] CSR_MISA_MXL = 2'b01; // XLEN=32

  localparam int CSR_MSIX_BIT   = 3;
  localparam int CSR_MTIX_BIT   = 7;
  localparam int CSR_MEIX_BIT   = 11;
  localparam int CSR_MFIX_BIT_LOW  = 16;
  localparam int CSR_MFIX_BIT_HIGH = 30;

  function automatic pmp_cfg_full_t pmp_cfg_decode(logic [PMP_CFG_W-1:0] cfg_val);
    pmp_cfg_full_t cfg;
    cfg.lock   = cfg_val[7];
    cfg.mode   = cfg_val[4:3];
    cfg.perm.r = cfg_val[0];
    cfg.perm.w = cfg_val[1];
    cfg.perm.x = cfg_val[2];
    return cfg;
  endfunction

  localparam pmp_cfg_t PmpCfgRst [PMP_MAX_REGIONS] = '{
    '{l: 1'b0, a: 2'b00}, '{l: 1'b0, a: 2'b00},
    '{l: 1'b0, a: 2'b00}, '{l: 1'b0, a: 2'b00},
    '{l: 1'b0, a: 2'b00}, '{l: 1'b0, a: 2'b00},
    '{l: 1'b0, a: 2'b00}, '{l: 1'b0, a: 2'b00},
    '{l: 1'b0, a: 2'b00}, '{l: 1'b0, a: 2'b00},
    '{l: 1'b0, a: 2'b00}, '{l: 1'b0, a: 2'b00},
    '{l: 1'b0, a: 2'b00}, '{l: 1'b0, a: 2'b00},
    '{l: 1'b0, a: 2'b00}, '{l: 1'b0, a: 2'b00}
  };

  localparam logic [PMP_ADDR_MSB:0] PmpAddrRst [PMP_MAX_REGIONS] = '{
    default: '0
  };

  localparam pmp_mseccfg_t PmpMseccfgRst = '{rlb: 1'b0, mmwp: 1'b0, mml: MML_NONE};

endpackage

