module ibex_register_file_ff #(
  parameter bit RV32E = 1'b0,
  parameter int unsigned DataWidth = 32,
  parameter bit DummyInstructions = 1'b0
) (
  input  logic                          clk_i,
  input  logic                          rst_ni,

  input  logic [4:0]                    raddr_a_i,
  input  logic [4:0]                    raddr_b_i,
  output logic [DataWidth-1:0]          rdata_a_o,
  output logic [DataWidth-1:0]          rdata_b_o,

  input  logic [4:0]                    waddr_a_i,
  input  logic [DataWidth-1:0]          wdata_a_i,
  input  logic                          we_a_i,

  input  logic                          dummy_instr_id_i,
  output logic                          dummy_instr_wb_o
);
  localparam int unsigned NUM_WORDS = RV32E ? 16 : 32;

  logic [DataWidth-1:0] mem [NUM_WORDS];
  logic [NUM_WORDS-1:0] we_a_dec;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      for (int i = 0; i < NUM_WORDS; i++) begin
        mem[i] <= '0;
      end
    end else begin
      if (we_a_i) begin
        mem[waddr_a_i] <= wdata_a_i;
      end
    end
  end

  assign rdata_a_o = (raddr_a_i == 5'b0) ? '0 : mem[raddr_a_i[4:0]];
  assign rdata_b_o = (raddr_b_i == 5'b0) ? '0 : mem[raddr_b_i[4:0]];

  assign dummy_instr_wb_o = dummy_instr_id_i;

endmodule

module ibex_register_file_fpga #(
  parameter bit RV32E = 1'b0,
  parameter int unsigned DataWidth = 32,
  parameter bit DummyInstructions = 1'b0
) (
  input  logic                          clk_i,
  input  logic                          rst_ni,

  input  logic [4:0]                    raddr_a_i,
  input  logic [4:0]                    raddr_b_i,
  output logic [DataWidth-1:0]          rdata_a_o,
  output logic [DataWidth-1:0]          rdata_b_o,

  input  logic [4:0]                    waddr_a_i,
  input  logic [DataWidth-1:0]          wdata_a_i,
  input  logic                          we_a_i,

  input  logic                          dummy_instr_id_i,
  output logic                          dummy_instr_wb_o
);
  localparam int unsigned NUM_WORDS = RV32E ? 16 : 32;

  logic [DataWidth-1:0] mem [NUM_WORDS];

  always_ff @(posedge clk_i) begin
    if (we_a_i) begin
      mem[waddr_a_i] <= wdata_a_i;
    end
  end

  always_ff @(posedge clk_i) begin
    rdata_a_o <= (raddr_a_i == 5'b0) ? '0 : mem[raddr_a_i[4:0]];
    rdata_b_o <= (raddr_b_i == 5'b0) ? '0 : mem[raddr_b_i[4:0]];
  end

  assign dummy_instr_wb_o = dummy_instr_id_i;

endmodule

module ibex_register_file_latch #(
  parameter bit RV32E = 1'b0,
  parameter int unsigned DataWidth = 32,
  parameter bit DummyInstructions = 1'b0
) (
  input  logic                          clk_i,
  input  logic                          rst_ni,

  input  logic [4:0]                    raddr_a_i,
  input  logic [4:0]                    raddr_b_i,
  output logic [DataWidth-1:0]          rdata_a_o,
  output logic [DataWidth-1:0]          rdata_b_o,

  input  logic [4:0]                    waddr_a_i,
  input  logic [DataWidth-1:0]          wdata_a_i,
  input  logic                          we_a_i,

  input  logic                          dummy_instr_id_i,
  output logic                          dummy_instr_wb_o
);
  localparam int unsigned NUM_WORDS = RV32E ? 16 : 32;

  logic [DataWidth-1:0] mem [NUM_WORDS];

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      for (int i = 0; i < NUM_WORDS; i++) begin
        mem[i] <= '0;
      end
    end else if (we_a_i) begin
      mem[waddr_a_i] <= wdata_a_i;
    end
  end

  assign rdata_a_o = (raddr_a_i == 5'b0) ? '0 : mem[raddr_a_i[4:0]];
  assign rdata_b_o = (raddr_b_i == 5'b0) ? '0 : mem[raddr_b_i[4:0]];

  assign dummy_instr_wb_o = dummy_instr_id_i;

endmodule

module ibex_branch_predict #(
  parameter bit BranchPredictor = 1'b0
) (
  input  logic        clk_i,
  input  logic        rst_ni,

  input  logic [31:0] fetch_rdata_i,
  input  logic [31:0] fetch_pc_i,
  input  logic        fetch_valid_i,

  output logic [31:0] predict_addr_o,
  output logic        predict_branch_o
);
  if (BranchPredictor) begin : gen_branch_predict
    logic [31:0] branch_target;

    always_comb begin
      predict_branch_o = 1'b0;
      predict_addr_o   = '0;

      if (fetch_valid_i) begin
        if (fetch_rdata_i[6:0] == 7'b1100011 || fetch_rdata_i[6:0] == 7'b1101111) begin
          if (fetch_rdata_i[6:0] == 7'b1101111) begin
            predict_branch_o = 1'b1;
            predict_addr_o   = fetch_pc_i + {{12{fetch_rdata_i[31]}}, fetch_rdata_i[31:12]};
          end else begin
            logic [31:0] imm_b;
            imm_b = {{20{fetch_rdata_i[31]}}, fetch_rdata_i[7], fetch_rdata_i[30:25],
                      fetch_rdata_i[11:8], 1'b0};
            if (fetch_rdata_i[31] == 1'b1) begin
              predict_branch_o = 1'b1;
              predict_addr_o   = fetch_pc_i + imm_b;
            end
          end
        end
      end
    end
  end else begin : gen_no_branch_predict
    assign predict_branch_o = 1'b0;
    assign predict_addr_o   = '0;
  end

endmodule

module ibex_compressed_decoder (
  input  logic [31:0] instr_i,
  output logic [31:0] instr_o,
  output logic        is_compressed_o,
  output logic        illegal_instr_o
);
  logic [15:0] instr;
  assign instr = instr_i[15:0];

  always_comb begin
    instr_o         = {instr_i[31:16], instr};
    is_compressed_o = 1'b0;
    illegal_instr_o = 1'b0;

    unique case (instr[1:0])
      2'b00: begin
        unique case (instr[15:13])
          3'b000: begin
            if (instr[12:5] == 8'b0 && instr[6:2] == 5'b0) begin
              is_compressed_o = 1'b0;
            end else begin
              is_compressed_o = 1'b1;
              instr_o = {7'b0000000, instr[12], instr[6:2], 5'b00010, 3'b000, {instr[11:7]}, 7'b0010011};
              if (instr[12:5] == 8'b0 && instr[11:7] == 5'b0) begin
                illegal_instr_o = 1'b1;
              end
            end
          end
          3'b001: begin
            is_compressed_o = 1'b1;
            instr_o = {5'b00000, instr[12], instr[6:2], 5'b00010, 3'b000, {instr[11:7]}, 7'b0010011};
          end
          3'b010: begin
            is_compressed_o = 1'b1;
            instr_o = {5'b00000, instr[12], instr[6:2], {instr[11:7]}, 3'b010, 5'b00010, 7'b0000111};
          end
          3'b011: begin
            is_compressed_o = 1'b1;
            instr_o = {5'b00000, instr[12], instr[6:2], {instr[11:7]}, 3'b010, 5'b00010, 7'b0001111};
          end
          3'b100: begin
            is_compressed_o = 1'b1;
            unique case (instr[11:10])
              2'b00: instr_o = {7'b0100000, 5'b00000, instr[12], instr[6:2], {instr[11:7]}, 7'b0110011};
              2'b01: instr_o = {7'b0000000, 5'b00000, instr[12], instr[6:2], {instr[11:7]}, 7'b0110011};
              2'b10: instr_o = {7'b0000000, instr[12], instr[6:2], 5'b00001, 3'b100, {instr[11:7]}, 7'b0010011};
              2'b11: instr_o = {7'b0100000, instr[12], instr[6:2], 5'b00001, 3'b101, {instr[11:7]}, 7'b0010011};
              default: ;
            endcase
          end
          3'b101: begin
            is_compressed_o = 1'b1;
            instr_o = {7'b0100000, instr[12], instr[6:2], 5'b00001, 3'b101, {instr[11:7]}, 7'b0010011};
          end
          3'b110: begin
            is_compressed_o = 1'b1;
            instr_o = {7'b0000000, instr[12], instr[6:2], 5'b00001, 3'b101, {instr[11:7]}, 7'b0010011};
          end
          3'b111: begin
            is_compressed_o = 1'b1;
            instr_o = {7'b0000000, instr[12], instr[6:2], 5'b00001, 3'b111, {instr[11:7]}, 7'b0010011};
          end
          default: ;
        endcase
      end
      2'b01: begin
        unique case (instr[15:13])
          3'b000: begin
            is_compressed_o = 1'b1;
            instr_o = {{6{instr[12]}}, instr[12], instr[10:5], instr[12], instr[11], instr[4:0],
                        5'b00000, 3'b000, {instr[11:7]}, 7'b0010011};
          end
          3'b001: begin
            is_compressed_o = 1'b1;
            instr_o = {{6{instr[12]}}, instr[12], instr[10:5], instr[12], instr[11], instr[4:0],
                        5'b00000, 3'b000, {instr[11:7]}, 7'b0001011};
          end
          3'b010: begin
            is_compressed_o = 1'b1;
            instr_o = {5'b00000, 7'b0000000, instr[12], instr[6:2], {instr[11:7]}, 3'b010, 5'b00000, 7'b0100011};
          end
          3'b011: begin
            is_compressed_o = 1'b1;
            instr_o = {5'b00000, 7'b0000000, instr[12], instr[6:2], {instr[11:7]}, 3'b010, 5'b00010, 7'b0100011};
          end
          3'b100: begin
            is_compressed_o = 1'b1;
            unique case (instr[11:10])
              2'b00: begin
                instr_o = {7'b0000000, 2'b00, instr[4], instr[9:7], instr[10], instr[6], instr[3],
                           2'b00, instr[5], {instr[11:7]}, 3'b001, {instr[4:2] + 5'b01000}, 7'b0100011};
              end
              2'b01: begin
                instr_o = {7'b0000000, 2'b01, instr[5:4], instr[9:7], instr[10], instr[6], instr[3],
                           2'b00, instr[5], {instr[11:7]}, 3'b001, {instr[4:2] + 5'b01000}, 7'b0100011};
              end
              2'b10: begin
                instr_o = {7'b0000000, 2'b10, instr[5:4], instr[9:7], instr[10], instr[6], instr[3],
                           2'b00, instr[5], {instr[11:7]}, 3'b001, {instr[4:2] + 5'b01000}, 7'b0100011};
              end
              2'b11: begin
                unique case (instr[12])
                  1'b0: begin
                    if (instr[6:2] == 5'b00000 && instr[11:7] == 5'b00000) begin
                      instr_o = {12'b0, 5'b00001, 3'b000, 5'b00000, 7'b1110011};
                    end else begin
                      instr_o = {7'b0000000, instr[6:2], 5'b00000, 3'b000, {instr[11:7]}, 7'b0010011};
                    end
                  end
                  1'b1: begin
                    if (instr[6:2] == 5'b00000 && instr[11:7] == 5'b00000) begin
                      instr_o = {12'b0, 5'b00001, 3'b000, 5'b00000, 7'b1110011};
                    end else begin
                      instr_o = {7'b0100000, instr[6:2], 5'b00000, 3'b000, {instr[11:7]}, 7'b0010011};
                    end
                  end
                  default: ;
                endcase
              end
              default: ;
            endcase
          end
          3'b101: begin
            is_compressed_o = 1'b1;
            instr_o = {{7{instr[12]}}, instr[6:2], 5'b00000, 3'b000, {instr[11:7]}, 7'b1101111};
          end
          3'b110: begin
            is_compressed_o = 1'b1;
            instr_o = {{7{instr[12]}}, instr[6:2], 5'b00000, 3'b000, {instr[11:7]}, 7'b1100111};
          end
          3'b111: begin
            is_compressed_o = 1'b1;
            instr_o = {{7{instr[12]}}, instr[12], instr[6:2], 5'b00000, 3'b000, 5'b00000, 7'b1101111};
          end
          default: ;
        endcase
      end
      2'b10: begin
        unique case (instr[15:13])
          3'b000: begin
            is_compressed_o = 1'b1;
            instr_o = {5'b00000, 7'b0000000, instr[12], instr[6:2], {instr[11:7]}, 3'b010, 5'b00000, 7'b0000011};
          end
          3'b001: begin
            is_compressed_o = 1'b1;
            instr_o = {5'b00000, 7'b0000000, instr[12], instr[6:2], {instr[11:7]}, 3'b010, 5'b00010, 7'b0000011};
          end
          3'b010: begin
            is_compressed_o = 1'b1;
            instr_o = {5'b00000, 7'b0000000, instr[12], instr[6:2], {instr[11:7]}, 3'b010, 5'b00001, 7'b0000011};
          end
          3'b011: begin
            is_compressed_o = 1'b1;
            instr_o = {{6{instr[12]}}, instr[12], instr[6:2], 5'b00000, 3'b000, {instr[11:7]}, 7'b0010011};
          end
          3'b100: begin
            is_compressed_o = 1'b1;
            unique case (instr[12])
              1'b0: begin
                instr_o = {5'b00000, 7'b0000000, 5'b00000, 3'b000, 5'b00000, 7'b1110011};
              end
              1'b1: begin
                unique case (instr[11:7])
                  5'b00000: instr_o = {12'b0, 5'b00000, 3'b000, 5'b00000, 7'b1110011};
                  5'b00010: instr_o = {12'b0, 5'b00001, 3'b000, 5'b00000, 7'b1110011};
                  default:   illegal_instr_o = 1'b1;
                endcase
              end
              default: ;
            endcase
          end
          3'b101: begin
            is_compressed_o = 1'b1;
            instr_o = {7'b0000000, 5'b00000, 5'b00000, 3'b000, 5'b00000, 7'b1110011};
          end
          3'b110: begin
            is_compressed_o = 1'b1;
            instr_o = {7'b0000000, 5'b00000, 5'b00000, 3'b000, 5'b00000, 7'b1110011};
          end
          3'b111: begin
            is_compressed_o = 1'b1;
            instr_o = {7'b0000000, 5'b00000, 5'b00000, 3'b000, 5'b00000, 7'b1110011};
          end
          default: ;
        endcase
      end
      2'b11: begin
        is_compressed_o = 1'b0;
      end
      default: ;
    endcase
  end

endmodule

module ibex_alu #(
  parameter ibex_pkg::rv32b_e RV32B = ibex_pkg::RV32BNone
) (
  input  ibex_pkg::alu_op_e operator_i,
  input  logic [31:0]       operand_a_i,
  input  logic [31:0]       operand_b_i,

  input  logic               instr_first_cycle_i,

  output logic [31:0]        result_o,
  output logic               comparison_result_o,

  output logic [31:0]        adder_result_o,
  output logic [33:0]        imd_val_q_o [2],
  input  logic [33:0]        imd_val_d_i [2],
  input  logic [1:0]         imd_val_we_i
);
  import ibex_pkg::*;

  logic [31:0] operand_a, operand_b;
  logic [32:0] adder_in_a, adder_in_b;
  logic [32:0] adder_result_ext;
  logic [31:0] adder_result;
  logic        adder_subtract;
  logic        is_equal, is_less, is_less_unsigned;

  logic [31:0] shift_result;
  logic [4:0]  shift_amt;

  logic [31:0] logic_result;

  always_comb begin
    operand_a = operand_a_i;
    operand_b = operand_b_i;
    adder_subtract = 1'b0;

    unique case (operator_i)
      ALU_ADD: ;
      ALU_SUB: adder_subtract = 1'b1;
      ALU_EQ, ALU_NE: adder_subtract = 1'b1;
      ALU_LT, ALU_LTU, ALU_GE, ALU_GEU: adder_subtract = 1'b1;
      ALU_SLT, ALU_SLTU: adder_subtract = 1'b1;
      default: ;
    endcase
  end

  assign adder_in_a = {operand_a, 1'b1};
  assign adder_in_b = {operand_b, ~adder_subtract};

  assign adder_result_ext = adder_in_a + adder_in_b;
  assign adder_result     = adder_result_ext[32:1];
  assign adder_result_o   = adder_result;

  assign is_equal = (operand_a == operand_b);
  assign is_less_unsigned = (operand_a < operand_b);
  assign is_less = (operand_a[31] != operand_b[31]) ? operand_a[31] :
                   (operand_a < operand_b);

  always_comb begin
    unique case (operator_i)
      ALU_EQ:  comparison_result_o = is_equal;
      ALU_NE:  comparison_result_o = !is_equal;
      ALU_LT:  comparison_result_o = is_less;
      ALU_LTU: comparison_result_o = is_less_unsigned;
      ALU_GE:  comparison_result_o = !is_less;
      ALU_GEU: comparison_result_o = !is_less_unsigned;
      ALU_SLT:  comparison_result_o = is_less;
      ALU_SLTU: comparison_result_o = is_less_unsigned;
      default: comparison_result_o = is_equal;
    endcase
  end

  assign shift_amt = operand_b_i[4:0];

  always_comb begin
    unique case (operator_i)
      ALU_SLL: shift_result = operand_a_i << shift_amt;
      ALU_SRL: shift_result = operand_a_i >> shift_amt;
      ALU_SRA: shift_result = $signed(operand_a_i) >>> shift_amt;
      default: shift_result = operand_a_i >> shift_amt;
    endcase
  end

  always_comb begin
    unique case (operator_i)
      ALU_XOR: logic_result = operand_a_i ^ operand_b_i;
      ALU_OR:  logic_result = operand_a_i | operand_b_i;
      ALU_AND: logic_result = operand_a_i & operand_b_i;
      default: logic_result = operand_a_i | operand_b_i;
    endcase
  end

  always_comb begin
    unique case (operator_i)
      ALU_ADD, ALU_SUB: result_o = adder_result;
      ALU_XOR, ALU_OR, ALU_AND: result_o = logic_result;
      ALU_SLL, ALU_SRL, ALU_SRA: result_o = shift_result;
      ALU_EQ, ALU_NE: result_o = {31'b0, comparison_result_o};
      ALU_LT, ALU_LTU, ALU_GE, ALU_GEU: result_o = {31'b0, comparison_result_o};
      ALU_SLT, ALU_SLTU: result_o = {31'b0, comparison_result_o};
      default: result_o = adder_result;
    endcase
  end

  for (genvar i = 0; i < 2; i++) begin : gen_imd_reg
    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        imd_val_q_o[i] <= '0;
      end else if (imd_val_we_i[i]) begin
        imd_val_q_o[i] <= imd_val_d_i[i];
      end
    end
  end

endmodule

module ibex_alu #(
  parameter ibex_pkg::rv32b_e RV32B = ibex_pkg::RV32BNone
) (
  input  ibex_pkg::alu_op_e operator_i,
