  assign adder_in_a = {operand_a_i, 1'b1};
  assign adder_in_b = {operand_b_i, ~adder_subtract};
  assign adder_result_ext = adder_in_a + adder_in_b;
  assign adder_result     = adder_result_ext[32:1];
