                          (operand_a_i < operand_b_i);

  always_comb begin
    unique case (operator_i)
      ALU_EQ:   comparison_result_o = is_equal;
      ALU_NE:   comparison_result_o = !is_equal;
      ALU_LT:   comparison_result_o = is_less_signed;
      ALU_LTU:  comparison_result_o = is_less_unsigned;
      ALU_GE:   comparison_result_o = !is_less_signed;
      ALU_GEU:  comparison_result_o = !is_less_unsigned;
      ALU_SLT:  comparison_result_o = is_less_signed;
      ALU_SLTU: comparison_result_o = is_less_unsigned;
      default:  comparison_result_o = is_equal;
