module ibex_multdiv_fast (
  input  logic                clk_i,
  input  logic                rst_ni,
  input  logic                mult_en_i,
  input  logic                div_en_i,
  input  ibex_pkg::md_op_e   operator_i,
  input  logic [1:0]          signed_mode_i,
  input  logic [31:0]         op_a_i,
  input  logic [31:0]         op_b_i,
  input  logic                data_ind_timing_i,

  output logic [31:0]         result_o,
  output logic                multdiv_ready_o,
  output logic                multdiv_valid_o
);
  import ibex_pkg::*;

  logic [33:0] imd_val_d, imd_val_q;
  logic        imd_val_we;

  logic [31:0] mult_op_a, mult_op_b;
  logic [63:0] mult_result;
  logic [31:0] mult_result_lower, mult_result_upper;
  logic [31:0] div_result;
  logic        div_en_internal;
  logic [5:0]  div_counter_q, div_counter_d;
  logic        div_busy_q, div_busy_d;
  logic [31:0] div_remainder_q, div_remainder_d;
  logic [31:0] div_quotient_q, div_quotient_d;
  logic [31:0] div_operand_a, div_operand_b;
  logic        div_sign_a, div_sign_b;
  logic [31:0] div_op_a_abs, div_op_b_abs;

  assign multdiv_ready_o = ~div_busy_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      div_busy_q <= 1'b0;
      div_counter_q <= '0;
      div_remainder_q <= '0;
      div_quotient_q <= '0;
      imd_val_q <= '0;
    end else begin
      div_busy_q <= div_busy_d;
      div_counter_q <= div_counter_d;
      div_remainder_q <= div_remainder_d;
      div_quotient_q <= div_quotient_d;
      if (imd_val_we) begin
        imd_val_q <= imd_val_d;
      end
    end
  end

  assign mult_op_a = op_a_i;
  assign mult_op_b = op_b_i;
  assign mult_result = $signed(mult_op_a) * $signed(mult_op_b);

  always_comb begin
    mult_result_lower = mult_result[31:0];
    mult_result_upper = mult_result[63:32];
  end

  always_comb begin
    div_operand_a = op_a_i;
    div_operand_b = op_b_i;
    div_sign_a = 1'b0;
    div_sign_b = 1'b0;
    div_op_a_abs = op_a_i;
    div_op_b_abs = op_b_i;

    if (signed_mode_i[0] && op_a_i[31]) begin
      div_sign_a = 1'b1;
      div_op_a_abs = -op_a_i;
    end
    if (signed_mode_i[1] && op_b_i[31]) begin
      div_sign_b = 1'b1;
      div_op_b_abs = -op_b_i;
    end
  end

  always_comb begin
    div_busy_d = div_busy_q;
    div_counter_d = div_counter_q;
    div_remainder_d = div_remainder_q;
    div_quotient_d = div_quotient_q;
    div_en_internal = 1'b0;
    div_result = '0;
    imd_val_d = '0;
    imd_val_we = 1'b0;
    multdiv_valid_o = 1'b0;

    if (mult_en_i && !div_busy_q) begin
      unique case (operator_i)
        MD_OP_MULL: begin
          result_o = mult_result_lower;
          multdiv_valid_o = 1'b1;
        end
        MD_OP_MULH: begin
          result_o = mult_result_upper;
          multdiv_valid_o = 1'b1;
        end
        MD_OP_MULHsu: begin
          result_o = $unsigned($signed(op_a_i) * $unsigned(op_b_i)) >> 32;
          multdiv_valid_o = 1'b1;
        end
        MD_OP_MULHU: begin
          result_o = ($unsigned(op_a_i) * $unsigned(op_b_i)) >> 32;
          multdiv_valid_o = 1'b1;
        end
        default: begin
          result_o = mult_result_lower;
          multdiv_valid_o = 1'b1;
        end
      endcase
    end else if (div_en_i && !div_busy_q) begin
      div_en_internal = 1'b1;
      div_busy_d = 1'b1;
      div_counter_d = 6'd1;
      div_remainder_d = '0;
      div_quotient_d = div_op_a_abs;
      imd_val_d = {2'b0, div_op_b_abs};
      imd_val_we = 1'b1;
      result_o = '0;
      multdiv_valid_o = 1'b0;
    end else if (div_busy_q) begin
      logic [31:0] divisor;
      logic [31:0] remainder_next;
      logic [31:0] quotient_next;
      logic        bit_val;

      divisor = imd_val_q[31:0];
      remainder_next = {div_remainder_q[30:0], div_quotient_q[31]};

      if (remainder_next >= divisor) begin
        remainder_next = remainder_next - divisor;
        bit_val = 1'b1;
      end else begin
        bit_val = 1'b0;
      end
      quotient_next = {div_quotient_q[30:0], bit_val};

      div_remainder_d = remainder_next;
      div_quotient_d = quotient_next;
      div_counter_d = div_counter_q + 6'd1;

      if (data_ind_timing_i) begin
        if (div_counter_q == 6'd33) begin
          div_busy_d = 1'b0;
          multdiv_valid_o = 1'b1;
        end
      end else begin
        if (div_counter_q == 6'd33) begin
          div_busy_d = 1'b0;
          multdiv_valid_o = 1'b1;
        end
      end

      if (!div_busy_d) begin
        unique case (operator_i)
          MD_OP_DIV, MD_OP_DIVU: begin
            logic signed_div;
            signed_div = (operator_i == MD_OP_DIV) && (div_sign_a ^ div_sign_b);
            if (op_b_i == 32'b0) begin
              div_result = 32'hffffffff;
            end else if (operator_i == MD_OP_DIV && op_a_i == 32'h80000000 && op_b_i == 32'hffffffff) begin
              div_result = 32'h80000000;
            end else begin
              div_result = signed_div ? -quotient_next : quotient_next;
            end
          end
          MD_OP_REM, MD_OP_REMU: begin
            if (op_b_i == 32'b0) begin
              div_result = op_a_i;
            end else if (operator_i == MD_OP_REM && op_a_i == 32'h80000000 && op_b_i == 32'hffffffff) begin
              div_result = 32'b0;
            end else begin
              div_result = div_sign_a ? -remainder_next : remainder_next;
            end
          end
          default: div_result = quotient_next;
        endcase
        result_o = div_result;
      end else begin
        result_o = '0;
      end
    end else begin
      result_o = '0;
    end
  end

endmodule

module ibex_multdiv_fast (
  input  logic                clk_i,
  input  logic                rst_ni,
  input  logic                mult_en_i,
  input  logic                div_en_i,
  input  ibex_pkg::md_op_e   operator_i,
  input  logic [1:0]          signed_mode_i,
  input  logic [31:0]         op_a_i,
  input  logic [31:0]         op_b_i,
  input  logic                data_ind_timing_i,

  output logic [31:0]         result_o,
  output logic                multdiv_ready_o,
  output logic                multdiv_valid_o
);
  import ibex_pkg::*;

  localparam int CYCLES = 33;

  logic [5:0]  div_cnt_q, div_cnt_d;
  logic        div_busy_q, div_busy_d;
  logic [31:0] res_q, res_d;
  logic [31:0] rem_q, rem_d;
  logic [31:0] op_b_q;
  logic        op_a_sign, op_b_sign;
  logic [31:0] op_a_abs, op_b_abs;

  logic [31:0] mult_result;
  logic [63:0] full_mult;

  assign multdiv_ready_o = ~div_busy_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      div_busy_q <= 1'b0;
      div_cnt_q  <= '0;
      res_q      <= '0;
      rem_q      <= '0;
      op_b_q     <= '0;
    end else begin
      div_busy_q <= div_busy_d;
      div_cnt_q  <= div_cnt_d;
      res_q      <= res_d;
      rem_q      <= rem_d;
      if (div_en_i && !div_busy_q) begin
        op_b_q <= op_b_abs;
      end
    end
  end

  assign op_a_sign = signed_mode_i[0] & op_a_i[31];
  assign op_b_sign = signed_mode_i[1] & op_b_i[31];
  assign op_a_abs  = op_a_sign ? -op_a_i : op_a_i;
  assign op_b_abs  = op_b_sign ? -op_b_i : op_b_i;

  assign full_mult = $unsigned(op_a_i) * $unsigned(op_b_i);

  always_comb begin
    div_busy_d  = div_busy_q;
    div_cnt_d   = div_cnt_q;
    res_d       = res_q;
    rem_d       = rem_q;
    result_o    = '0;
    multdiv_valid_o = 1'b0;

    if (mult_en_i && !div_busy_q) begin
      unique case (operator_i)
        MD_OP_MULL:  result_o = full_mult[31:0];
        MD_OP_MULHU: result_o = full_mult[63:32];
        MD_OP_MULHsu: begin
          result_o = $unsigned($signed(op_a_i) * $unsigned(op_b_i)) >> 32;
        end
        MD_OP_MULH: begin
          result_o = $unsigned($signed(op_a_i) * $signed(op_b_i)) >> 32;
        end
        default: result_o = full_mult[31:0];
      endcase
      multdiv_valid_o = 1'b1;
    end else if (div_en_i && !div_busy_q) begin
      div_busy_d = 1'b1;
      div_cnt_d  = 6'd1;
      rem_d      = '0;
      res_d      = op_a_abs;
    end else if (div_busy_q) begin
      logic [31:0] next_rem;
      logic        q_bit;
      next_rem = {rem_q[30:0], res_q[31]};
      if (next_rem >= op_b_q) begin
        next_rem = next_rem - op_b_q;
        q_bit = 1'b1;
      end else begin
        q_bit = 1'b0;
      end
      rem_d = next_rem;
      res_d = {res_q[30:0], q_bit};
      div_cnt_d = div_cnt_q + 6'd1;

      if (div_cnt_q == 6'd33) begin
        div_busy_d = 1'b0;
        multdiv_valid_o = 1'b1;
        unique case (operator_i)
          MD_OP_DIV, MD_OP_DIVU: begin
            if (op_b_i == '0) begin
              result_o = 32'hffffffff;
            end else if (operator_i == MD_OP_DIV && op_a_i == 32'h80000000 && op_b_i == 32'hffffffff) begin
              result_o = 32'h80000000;
            end else begin
              result_o = (op_a_sign ^ op_b_sign) ? -res_d : res_d;
            end
          end
          MD_OP_REM, MD_OP_REMU: begin
            if (op_b_i == '0) begin
              result_o = op_a_i;
            end else if (operator_i == MD_OP_REM && op_a_i == 32'h80000000 && op_b_i == 32'hffffffff) begin
              result_o = 32'b0;
            end else begin
              result_o = op_a_sign ? -rem_d : rem_d;
            end
          end
          default: result_o = res_d;
        endcase
      end
    end
  end

endmodule

module ibex_multdiv_fast (
  input  logic                clk_i,
  input  logic                rst_ni,
  input  logic                mult_en_i,
  input  logic                div_en_i,
  input  ibex_pkg::md_op_e   operator_i,
  input  logic [1:0]          signed_mode_i,
  input  logic [31:0]         op_a_i,
  input  logic [31:0]         op_b_i,
  input  logic                data_ind_timing_i,

  output logic [31:0]         result_o,
  output logic                multdiv_ready_o,
  output logic                multdiv_valid_o
);
  import ibex_pkg::*;

  localparam int CYCLES = 33;

  logic [5:0]  div_cnt_q, div_cnt_d;
  logic        div_busy_q, div_busy_d;
  logic [31:0] res_q, res_d;
  logic [31:0] rem_q, rem_d;
  logic [31:0] div_op_b_q;
  logic        op_a_sign, op_b_sign;
  logic [31:0] op_a_abs, op_b_abs;
  logic [31:0] next_rem;
  logic        q_bit;
  logic [63:0] full_mult;

  assign multdiv_ready_o = ~div_busy_q;
  assign op_a_sign = signed_mode_i[0] & op_a_i[31];
  assign op_b_sign = signed_mode_i[1] & op_b_i[31];
  assign op_a_abs  = op_a_sign ? -op_a_i : op_a_i;
  assign op_b_abs  = op_b_sign ? -op_b_i : op_b_i;

  assign full_mult = $unsigned(op_a_i) * $unsigned(op_b_i);

  assign next_rem = {rem_q[30:0], res_q[31]};
  assign q_bit    = (next_rem >= div_op_b_q) ? 1'b1 : 1'b0;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      div_busy_q <= 1'b0;
      div_cnt_q  <= '0;
      res_q      <= '0;
      rem_q      <= '0;
      div_op_b_q <= '0;
    end else begin
      div_busy_q <= div_busy_d;
      div_cnt_q  <= div_cnt_d;
      res_q      <= res_d;
      rem_q      <= rem_d;
      if (div_en_i && !div_busy_q) begin
        div_op_b_q <= op_b_abs;
      end
    end
  end

  logic [31:0] final_quotient, final_remainder;
  assign final_quotient  = (q_bit) ? {res_q[30:0], 1'b1} : {res_q[30:0], 1'b0};
  assign final_remainder = (q_bit) ? (next_rem - div_op_b_q) : next_rem;

  always_comb begin
    div_busy_d  = div_busy_q;
    div_cnt_d   = div_cnt_q;
    res_d       = res_q;
    rem_d       = rem_q;
    result_o    = '0;
    multdiv_valid_o = 1'b0;

    if (mult_en_i && !div_busy_q) begin
      unique case (operator_i)
        MD_OP_MULL:  result_o = full_mult[31:0];
        MD_OP_MULHU: result_o = full_mult[63:32];
        MD_OP_MULHsu: result_o = $unsigned($signed(op_a_i) * $unsigned(op_b_i)) >> 32;
        MD_OP_MULH:  result_o = $unsigned($signed(op_a_i) * $signed(op_b_i)) >> 32;
        default:     result_o = full_mult[31:0];
      endcase
      multdiv_valid_o = 1'b1;
    end else if (div_en_i && !div_busy_q) begin
      div_busy_d = 1'b1;
      div_cnt_d  = 6'd1;
      rem_d      = '0;
      res_d      = op_a_abs;
    end else if (div_busy_q) begin
      rem_d = final_remainder;
      res_d = final_quotient;
      div_cnt_d = div_cnt_q + 6'd1;

      if (div_cnt_q == 6'd33) begin
        div_busy_d = 1'b0;
        multdiv_valid_o = 1'b1;
        if (op_b_i == '0) begin
          unique case (operator_i)
            MD_OP_DIV, MD_OP_DIVU: result_o = 32'hffffffff;
            MD_OP_REM, MD_OP_REMU: result_o = op_a_i;
            default:               result_o = final_quotient;
          endcase
        end else if (operator_i == MD_OP_DIV && op_a_i == 32'h80000000 && op_b_i == 32'hffffffff) begin
          result_o = 32'h80000000;
        end else if (operator_i == MD_OP_REM && op_a_i == 32'h80000000 && op_b_i == 32'hffffffff) begin
          result_o = 32'b0;
        end else begin
          unique case (operator_i)
            MD_OP_DIV, MD_OP_DIVU: result_o = (op_a_sign ^ op_b_sign) ? -final_quotient : final_quotient;
            MD_OP_REM, MD_OP_REMU: result_o = op_a_sign ? -final_remainder : final_remainder;
            default:               result_o = final_quotient;
          endcase
        end
      end
    end
  end

endmodule

module ibex_multdiv_slow (
  input  logic                clk_i,
  input  logic                rst_ni,
  input  logic                mult_en_i,
  input  logic                div_en_i,
  input  ibex_pkg::md_op_e   operator_i,
  input  logic [1:0]          signed_mode_i,
  input  logic [31:0]         op_a_i,
  input  logic [31:0]         op_b_i,
  input  logic                data_ind_timing_i,

  output logic [31:0]         result_o,
  output logic                multdiv_ready_o,
  output logic                multdiv_valid_o
);
  import ibex_pkg::*;

  logic [5:0]  cnt_q, cnt_d;
  logic        busy_q, busy_d;
  logic [31:0] res_q, res_d;
  logic [31:0] rem_q, rem_d;
  logic [31:0] op_b_q;
  logic        op_a_sign, op_b_sign;
  logic [31:0] op_a_abs, op_b_abs;

  assign multdiv_ready_o = ~busy_q;
  assign op_a_sign = signed_mode_i[0] & op_a_i[31];
  assign op_b_sign = signed_mode_i[1] & op_b_i[31];
  assign op_a_abs  = op_a_sign ? -op_a_i : op_a_i;
  assign op_b_abs  = op_b_sign ? -op_b_i : op_b_i;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      busy_q  <= 1'b0;
      cnt_q   <= '0;
      res_q   <= '0;
      rem_q   <= '0;
      op_b_q  <= '0;
    end else begin
      busy_q  <= busy_d;
      cnt_q   <= cnt_d;
      res_q   <= res_d;
      rem_q   <= rem_d;
      if ((mult_en_i || div_en_i) && !busy_q) begin
        op_b_q <= op_b_abs;
      end
    end
  end

  logic [31:0] next_rem;
  logic        q_bit;
  assign next_rem = {rem_q[30:0], res_q[31]};
  assign q_bit    = (next_rem >= op_b_q) ? 1'b1 : 1'b0;

  always_comb begin
    busy_d = busy_q;
    cnt_d  = cnt_q;
    res_d  = res_q;
    rem_d  = rem_q;
    result_o = '0;
    multdiv_valid_o = 1'b0;

    if (mult_en_i && !busy_q) begin
      busy_d = 1'b1;
      cnt_d  = 6'd1;
      rem_d  = '0;
      res_d  = op_a_abs;
    end else if (div_en_i && !busy_q) begin
      busy_d = 1'b1;
      cnt_d  = 6'd1;
      rem_d  = '0;
      res_d  = op_a_abs;
    end else if (busy_q) begin
      rem_d = q_bit ? (next_rem - op_b_q) : next_rem;
      res_d = {res_q[30:0], q_bit};
      cnt_d = cnt_q + 6'd1;

      if (cnt_q == 6'd33) begin
        busy_d = 1'b0;
        multdiv_valid_o = 1'b1;
        if (operator_i == MD_OP_DIV || operator_i == MD_OP_DIVU) begin
          if (op_b_i == '0)
            result_o = 32'hffffffff;
          else if (operator_i == MD_OP_DIV && op_a_i == 32'h80000000 && op_b_i == 32'hffffffff)
            result_o = 32'h80000000;
          else
            result_o = (op_a_sign ^ op_b_sign) ? -res_d : res_d;
        end else if (operator_i == MD_OP_REM || operator_i == MD_OP_REMU) begin
          if (op_b_i == '0)
            result_o = op_a_i;
          else if (operator_i == MD_OP_REM && op_a_i == 32'h80000000 && op_b_i == 32'hffffffff)
            result_o = 32'b0;
          else
            result_o = op_a_sign ? -rem_d : rem_d;
        end else begin
          unique case (operator_i)
            MD_OP_MULL:  result_o = res_d[31:0];
            MD_OP_MULH:  result_o = (op_a_sign ^ op_b_sign) ? -rem_d : rem_d;
            MD_OP_MULHsu: result_o = rem_d;
            MD_OP_MULHU: result_o = rem_d;
            default:     result_o = res_d;
          endcase
        end
      end
    end
  end

endmodule

module ibex_decoder #(
  parameter bit RV32E = 1'b0,
  parameter ibex_pkg::rv32m_e RV32M = ibex_pkg::RV32MFast,
  parameter ibex_pkg::rv32b_e RV32B = ibex_pkg::RV32BNone,
  parameter bit DataIndTiming = 1'b0
) (
  input  logic [31:0]          instr_rdata_i,
  input  logic                 illegal_c_insn_i,

  output ibex_pkg::alu_op_e    alu_operator_o,
  output logic [31:0]          operand_a_o,
  output logic [31:0]          operand_b_o,

  output logic                 mult_en_o,
  output logic                 div_en_o,
  output ibex_pkg::md_op_e     multdiv_operator_o,
  output logic [1:0]           multdiv_signed_mode_o,

  output logic [4:0]           rf_raddr_a_o,
  output logic [4:0]           rf_raddr_b_o,
  output logic [4:0]           rf_waddr_o,
  output logic                 rf_we_o,
  output logic                 rf_ren_a_o,
  output logic                 rf_ren_b_o,

  output logic                 csr_access_o,
  output ibex_pkg::csr_op_e    csr_op_o,

  output logic                 lsu_req_o,
  output logic                 lsu_we_o,
  output logic [1:0]           lsu_type_o,
  output logic                 lsu_sign_ext_o,

  output logic                 branch_o,
  output logic                 jump_o,

  output logic                 illegal_insn_o,
  output logic                 ebrk_insn_o,
  output logic                 ecall_insn_o,
  output logic                 mret_insn_o,
  output logic                 dret_insn_o,
  output logic                 wfi_insn_o
);
  import ibex_pkg::*;

  logic [6:0] opcode;
  logic [2:0] funct3;
  logic [6:0] funct7;
  logic [31:0] imm_i, imm_s, imm_b, imm_u, imm_j;
  logic [31:0] imm;

  assign opcode = instr_rdata_i[6:0];
  assign funct3 = instr_rdata_i[14:12];
  assign funct7 = instr_rdata_i[31:25];

  assign imm_i = {{20{instr_rdata_i[31]}}, instr_rdata_i[31:20]};
  assign imm_s = {{20{instr_rdata_i[31]}}, instr_rdata_i[31:25], instr_rdata_i[11:7]};
  assign imm_b = {{19{instr_rdata_i[31]}}, instr_rdata_i[31], instr_rdata_i[7],
                   instr_rdata_i[30:25], instr_rdata_i[11:8], 1'b0};
  assign imm_u = {instr_rdata_i[31:12], 12'b0};
  assign imm_j = {{12{instr_rdata_i[31]}}, instr_rdata_i[19:12], instr_rdata_i[20],
                   instr_rdata_i[30:21], 1'b0};

  always_comb begin
    alu_operator_o      = ALU_ADD;
    operand_a_o         = '0;
    operand_b_o         = '0;
    mult_en_o           = 1'b0;
    div_en_o            = 1'b0;
    multdiv_operator_o  = MD_OP_MULL;
    multdiv_signed_mode_o = 2'b00;
    rf_raddr_a_o        = instr_rdata_i[19:15];
    rf_raddr_b_o        = instr_rdata_i[24:20];
    rf_waddr_o          = instr_rdata_i[11:7];
    rf_we_o             = 1'b0;
    rf_ren_a_o          = 1'b0;
    rf_ren_b_o          = 1'b0;
    csr_access_o        = 1'b0;
    csr_op_o            = CSR_OP_READ;
    lsu_req_o           = 1'b0;
    lsu_we_o            = 1'b0;
    lsu_type_o          = 2'b00;
    lsu_sign_ext_o      = 1'b0;
    branch_o            = 1'b0;
    jump_o              = 1'b0;
    illegal_insn_o      = 1'b0;
    ebrk_insn_o         = 1'b0;
    ecall_insn_o        = 1'b0;
    mret_insn_o         = 1'b0;
    dret_insn_o         = 1'b0;
    wfi_insn_o          = 1'b0;
    imm                 = '0;

    unique case (opcode)
      7'b0110111: begin // LUI
        rf_we_o     = 1'b1;
        operand_a_o = '0;
        operand_b_o = imm_u;
        alu_operator_o = ALU_ADD;
      end

      7'b0010111: begin // AUIPC
        rf_we_o     = 1'b1;
        operand_a_o = '0;
        operand_b_o = imm_u;
        alu_operator_o = ALU_ADD;
      end

      7'b1101111: begin // JAL
        rf_we_o     = 1'b1;
        rf_waddr_o  = instr_rdata_i[11:7];
        jump_o      = 1'b1;
        imm         = imm_j;
      end

      7'b1100111: begin // JALR
        rf_we_o     = 1'b1;
        rf_ren_a_o  = 1'b1;
        jump_o      = 1'b1;
        imm         = imm_i;
        if (funct3 != 3'b000) illegal_insn_o = 1'b1;
      end

      7'b1100011: begin // Branch
        branch_o   = 1'b1;
        rf_ren_a_o = 1'b1;
        rf_ren_b_o = 1'b1;
        imm        = imm_b;
        unique case (funct3)
          3'b000: alu_operator_o = ALU_EQ;
          3'b001: alu_operator_o = ALU_NE;
          3'b100: alu_operator_o = ALU_LT;
          3'b101: alu_operator_o = ALU_GE;
          3'b110: alu_operator_o = ALU_LTU;
          3'b111: alu_operator_o = ALU_GEU;
          default: illegal_insn_o = 1'b1;
        endcase
      end

      7'b0000011: begin // Loads
        rf_we_o      = 1'b1;
        rf_ren_a_o   = 1'b1;
        lsu_req_o    = 1'b1;
        lsu_we_o     = 1'b0;
        imm          = imm_i;
        operand_b_o  = imm_i;
        unique case (funct3)
          3'b000: begin lsu_type_o = 2'b10; lsu_sign_ext_o = 1'b1; end // LB
          3'b001: begin lsu_type_o = 2'b01; lsu_sign_ext_o = 1'b1; end // LH
          3'b010: begin lsu_type_o = 2'b00; lsu_sign_ext_o = 1'b0; end // LW
          3'b100: begin lsu_type_o = 2'b10; lsu_sign_ext_o = 1'b0; end // LBU
          3'b101: begin lsu_type_o = 2'b01; lsu_sign_ext_o = 1'b0; end // LHU
          default: illegal_insn_o = 1'b1;
        endcase
      end

      7'b0100011: begin // Stores
        rf_ren_a_o   = 1'b1;
        rf_ren_b_o   = 1'b1;
        lsu_req_o    = 1'b1;
        lsu_we_o     = 1'b1;
        imm          = imm_s;
        operand_b_o  = imm_s;
        rf_waddr_o   = instr_rdata_i[11:7];
        unique case (funct3)
          3'b000: lsu_type_o = 2'b10; // SB
          3'b001: lsu_type_o = 2'b01; // SH
          3'b010: lsu_type_o = 2'b00; // SW
          default: illegal_insn_o = 1'b1;
        endcase
      end

      7'b0010011: begin // I-type ALU
        rf_we_o     = 1'b1;
        rf_ren_a_o  = 1'b1;
        imm         = imm_i;
        operand_b_o = imm_i;
        unique case (funct3)
          3'b000: alu_operator_o = ALU_ADD;  // ADDI
          3'b010: alu_operator_o = ALU_SLT;  // SLTI
          3'b011: alu_operator_o = ALU_SLTU; // SLTIU
          3'b100: alu_operator_o = ALU_XOR;  // XORI
          3'b110: alu_operator_o = ALU_OR;   // ORI
          3'b111: alu_operator_o = ALU_AND;  // ANDI
          3'b001: begin // SLLI
            alu_operator_o = ALU_SLL;
            if (instr_rdata_i[31:25] != 7'b0) illegal_insn_o = 1'b1;
          end
          3'b101: begin // SRLI/SRAI
            if (instr_rdata_i[31:25] == 7'b0)
              alu_operator_o = ALU_SRL;
            else if (instr_rdata_i[31:25] == 7'b0100000)
              alu_operator_o = ALU_SRA;
            else
              illegal_insn_o = 1'b1;
          end
          default: illegal_insn_o = 1'b1;
        endcase
      end

      7'b0110011: begin // R-type ALU
        rf_we_o     = 1'b1;
        rf_ren_a_o  = 1'b1;
        rf_ren_b_o  = 1'b1;
        unique case (funct3)
          3'b000: begin
            if (funct7 == 7'b0)
              alu_operator_o = ALU_ADD;
            else if (funct7 == 7'b0100000)
              alu_operator_o = ALU_SUB;
            else
              illegal_insn_o = 1'b1;
          end
          3'b001: begin
            alu_operator_o = ALU_SLL;
            if (funct7 != 7'b0) illegal_insn_o = 1'b1;
          end
          3'b010: begin
            alu_operator_o = ALU_SLT;
            if (funct7 != 7'b0) illegal_insn_o = 1'b1;
          end
          3'b011: begin
            alu_operator_o = ALU_SLTU;
            if (funct7 != 7'b0) illegal_insn_o = 1'b1;
          end
          3'b100: begin
            alu_operator_o = ALU_XOR;
            if (funct7 != 7'b0) illegal_insn_o = 1'b1;
          end
          3'b101: begin
            if (funct7 == 7'b0)
              alu_operator_o = ALU_SRL;
            else if (funct7 == 7'b0100000)
              alu_operator_o = ALU_SRA;
            else
              illegal_insn_o = 1'b1;
          end
          3'b110: begin
            alu_operator_o = ALU_OR;
            if (funct7 != 7'b0) illegal_insn_o = 1'b1;
          end
          3'b111: begin
            alu_operator_o = ALU_AND;
            if (funct7 != 7'b0) illegal_insn_o = 1'b1;
          end
        endcase

        if (RV32M != RV32MNone && funct7 == 7'b0000001) begin
          illegal_insn_o = 1'b0;
          rf_ren_a_o = 1'b1;
          rf_ren_b_o = 1'b1;
          rf_we_o    = 1'b1;
          unique case (funct3)
            3'b000: begin mult_en_o = 1'b1; multdiv_operator_o = MD_OP_MULL;  multdiv_signed_mode_o = 2'b00; end
            3'b001: begin mult_en_o = 1'b1; multdiv_operator_o = MD_OP_MULH;  multdiv_signed_mode_o = 2'b11; end
            3'b010: begin mult_en_o = 1'b1; multdiv_operator_o = MD_OP_MULHsu; multdiv_signed_mode_o = 2'b10; end
            3'b011: begin mult_en_o = 1'b1; multdiv_operator_o = MD_OP_MULHU; multdiv_signed_mode_o = 2'b00; end
            3'b100: begin div_en_o = 1'b1;  multdiv_operator_o = MD_OP_DIV;   multdiv_signed_mode_o = 2'b11; end
            3'b101: begin div_en_o = 1'b1;  multdiv_operator_o = MD_OP_DIVU;  multdiv_signed_mode_o = 2'b00; end
            3'b110: begin div_en_o = 1'b1;  multdiv_operator_o = MD_OP_REM;   multdiv_signed_mode_o = 2'b11; end
            3'b111: begin div_en_o = 1'b1;  multdiv_operator_o = MD_OP_REMU;  multdiv_signed_mode_o = 2'b00; end
          endcase
          alu_operator_o = ALU_ADD;
        end
      end

      7'b1110011: begin // SYSTEM
        unique case (funct3)
          3'b000: begin
            unique case (instr_rdata_i[31:20])
              12'h000: ecall_insn_o = 1'b1;  // ECALL
              12'h001: ebrk_insn_o  = 1'b1;  // EBREAK
              12'h302: mret_insn_o  = 1'b1;  // MRET
              12'h7b2: dret_insn_o  = 1'b1;  // DRET
              12'h105: begin  // WFI
                wfi_insn_o = 1'b1;
              end
              default: illegal_insn_o = 1'b1;
            endcase
          end
          3'b001: begin // CSRRW
            csr_access_o = 1'b1;
            csr_op_o     = CSR_OP_WRITE;
            rf_we_o      = 1'b1;
            rf_ren_a_o   = 1'b1;
          end
          3'b010: begin // CSRRS
            csr_access_o = 1'b1;
            csr_op_o     = CSR_OP_SET;
            rf_we_o      = 1'b1;
            rf_ren_a_o   = 1'b1;
          end
          3'b011: begin // CSRRC
            csr_access_o = 1'b1;
            csr_op_o     = CSR_OP_CLEAR;
            rf_we_o      = 1'b1;
            rf_ren_a_o   = 1'b1;
          end
          3'b101: begin // CSRRWI
            csr_access_o = 1'b1;
            csr_op_o     = CSR_OP_WRITE;
            rf_we_o      = 1'b1;
          end
          3'b110: begin // CSRRSI
            csr_access_o = 1'b1;
            csr_op_o     = CSR_OP_SET;
            rf_we_o      = 1'b1;
          end
          3'b111: begin // CSRRCI
            csr_access_o = 1'b1;
            csr_op_o     = CSR_OP_CLEAR;
            rf_we_o      = 1'b1;
          end
          default: illegal_insn_o = 1'b1;
        endcase
      end

      7'b0001111: begin // FENCE
      end

      default: illegal_insn_o = 1'b1;
    endcase

    if (illegal_c_insn_i) begin
      illegal_insn_o = 1'b1;
    end
  end

endmodule

module ibex_controller #(
  parameter bit WritebackStage = 1'b0,
  parameter bit BranchPredictor = 1'b0,
  parameter bit MemECC = 1'b0
) (
  input  logic                clk_i,
  input  logic                rst_ni,

  input  logic                fetch_valid_i,
  input  logic                fetch_ready_i,

  input  logic [31:0]         instr_rdata_i,
  input  logic                instr_is_compressed_i,
  input  logic                instr_fetch_err_i,
  input  logic                instr_fetch_err_plus2_i,
  input  logic                illegal_c_insn_i,
  input  logic                illegal_insn_i,
  input  logic                ecall_insn_i,
  input  logic                ebrk_insn_i,
  input  logic                mret_insn_i,
  input  logic                dret_insn_i,
  input  logic                wfi_insn_i,
  input  logic                branch_i,
  input  logic                branch_decision_i,
  input  logic                jump_i,
  input  logic                csr_access_i,
  input  logic [31:0]         csr_addr_i,

  input  logic                lsu_req_i,
  input  logic                lsu_we_i,
  input  logic                lsu_rvalid_i,
  input  logic                lsu_load_err_i,
  input  logic                lsu_store_err_i,

  output logic                ctrl_busy_o,
  output logic                instr_valid_clear_o,
  output logic                pc_set_o,
  output ibex_pkg::pc_sel_e   pc_mux_o,
  output ibex_pkg::exc_pc_sel_e exc_pc_mux_o,
  output logic                exc_cause_o,
  output logic                csr_save_if_o,
  output logic                csr_save_id_o,
  output logic                csr_save_wb_o,
  output logic                csr_restore_mret_id_o,
  output logic                csr_restore_dret_id_o,
  output logic                csr_save_cause_o,
  output logic [31:0]         csr_mtval_o,

  input  logic                csr_mstatus_mie_i,
  input  logic                irq_pending_i,
  input  ibex_pkg::irqs_t     irqs_i,
  input  logic                irq_nm_i,
  output logic                nmi_mode_o,
  input  logic                priv_mode_i,

  input  logic                debug_req_i,
  input  logic                debug_mode_i,
  output logic                debug_mode_o,
  output logic                debug_mode_entering_o,
  output ibex_pkg::dbg_cause_e debug_cause_o,
  output logic                debug_csr_save_o,
  output logic                debug_single_step_o,
  output logic                debug_ebreakm_o,
  output logic                debug_ebreaku_o,
  output logic                trigger_match_o,

  output logic                id_in_ready_o,
  output logic                ex_valid_o,

  input  logic                rf_we_i,
  input  logic [4:0]          rf_waddr_i,

  output logic                perf_jump_o,
  output logic                perf_branch_o,
  output logic                perf_tbranch_o,
  output logic                perf_dside_wait_o,
  output logic                perf_mul_wait_o,
  output logic                perf_div_wait_o,

  output logic                icache_inval_o,

  output logic                en_wb_o,
  output ibex_pkg::wb_instr_type_e instr_type_wb_o,

  input  logic                ready_wb_i,

  output logic                instr_id_done_o,

  output logic                rvfi_flush_next_o,
  output logic                id_exception_o,
  output logic                exc_req_d,
  output logic                exc_req_lsu,
  output logic                ebreak_into_debug,
  output logic                irq_nm_int
);
  import ibex_pkg::*;

  typedef enum logic [3:0] {
    RESET, BOOT_SET, DECODE, FLUSH, IRQ_TAKEN,
    DBG_TAKEN_IF, DBG_TAKEN_ID, WB_STAGE,
    EXC_IRQ, EXC_DBG
  } ctrl_state_e;

  ctrl_state_e ctrl_fsm_cs, ctrl_fsm_ns;

  logic nmi_mode_q, nmi_mode_d;
  logic debug_mode_q, debug_mode_d;
  logic [31:0] mtval;
  logic exc_req;
  logic special_req;
  logic stall;
  logic halt_if;
  logic flush_id;
  logic illegal_insn_qual;
  logic [5:0] exc_cause_int;
  logic irq_nm_int_q;

  logic branch_taken;
  assign branch_taken = branch_i & branch_decision_i;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      ctrl_fsm_cs <= RESET;
      nmi_mode_q  <= 1'b0;
      debug_mode_q <= 1'b0;
      irq_nm_int_q <= 1'b0;
      mtval <= '0;
    end else begin
      ctrl_fsm_cs <= ctrl_fsm_ns;
      nmi_mode_q  <= nmi_mode_d;
      debug_mode_q <= debug_mode_d;
      irq_nm_int_q <= irq_nm_int;
      if (csr_save_cause_o) begin
        mtval <= csr_mtval_o;
      end
    end
  end

  assign nmi_mode_o = nmi_mode_q;
  assign debug_mode_o = debug_mode_q;

  assign irq_nm_int = irq_nm_i & ~nmi_mode_q & ~debug_mode_q;

  always_comb begin
    ctrl_fsm_ns       = ctrl_fsm_cs;
    pc_set_o          = 1'b0;
    pc_mux_o          = PC_BOOT;
    exc_pc_mux_o      = EXC_PC_IRQ;
    exc_cause_o       = 1'b0;
    csr_save_if_o     = 1'b0;
    csr_save_id_o     = 1'b0;
    csr_save_wb_o     = 1'b0;
    csr_restore_mret_id_o = 1'b0;
    csr_restore_dret_id_o = 1'b0;
    csr_save_cause_o  = 1'b0;
    csr_mtval_o       = '0;
    nmi_mode_d        = nmi_mode_q;
    debug_mode_d      = debug_mode_q;
    debug_csr_save_o  = 1'b0;
    debug_cause_o     = DBG_CAUSE_NONE;
    debug_mode_entering_o = 1'b0;
    debug_single_step_o   = 1'b0;
    debug_ebreakm_o       = 1'b0;
    debug_ebreaku_o       = 1'b0;
    trigger_match_o       = 1'b0;
    id_in_ready_o     = 1'b0;
    ex_valid_o        = 1'b0;
    ctrl_busy_o       = 1'b1;
    instr_valid_clear_o = 1'b0;
    icache_inval_o    = 1'b0;
    perf_jump_o       = 1'b0;
    perf_branch_o     = 1'b0;
    perf_tbranch_o    = 1'b0;
    en_wb_o           = 1'b0;
    instr_type_wb_o   = WB_INSTR_OTHER;
    instr_id_done_o   = 1'b0;
    rvfi_flush_next_o = 1'b0;
    id_exception_o    = 1'b0;
    exc_req_d         = 1'b0;
    exc_req_lsu       = 1'b0;
    ebreak_into_debug = 1'b0;

    unique case (ctrl_fsm_cs)
      RESET: begin
        ctrl_fsm_ns = BOOT_SET;
      end

      BOOT_SET: begin
        pc_set_o    = 1'b1;
        pc_mux_o    = PC_BOOT;
        ctrl_fsm_ns = DECODE;
      end

      DECODE: begin
        id_in_ready_o = 1'b1;
        ctrl_busy_o   = 1'b0;
        en_wb_o       = 1'b1;
        instr_type_wb_o = WB_INSTR_OTHER;

        if (fetch_valid_i) begin
          ctrl_busy_o = 1'b1;
          id_in_ready_o = 1'b1;

          if (instr_fetch_err_i) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_EXC;
            exc_pc_mux_o = EXC_PC_EXC;
            csr_save_id_o = 1'b1;
            csr_save_cause_o = 1'b1;
            exc_cause_o = 1'b0;
            id_exception_o = 1'b1;
            ctrl_fsm_ns = DECODE;
          end else if (illegal_insn_i || ecall_insn_i) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_EXC;
            exc_pc_mux_o = EXC_PC_EXC;
            csr_save_id_o = 1'b1;
            csr_save_cause_o = 1'b1;
            id_exception_o = 1'b1;
            if (ecall_insn_i)
              exc_cause_o = (priv_mode_i == PRIV_LVL_M) ? 1'b1 : 1'b0;
            else
              exc_cause_o = 1'b0;
            ctrl_fsm_ns = DECODE;
          end else if (ebrk_insn_i) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_EXC;
            exc_pc_mux_o = EXC_PC_DBD;
            csr_save_id_o = 1'b1;
            csr_save_cause_o = 1'b1;
            exc_cause_o = 1'b1;
            id_exception_o = 1'b1;
            ebreak_into_debug = 1'b1;
            ctrl_fsm_ns = DECODE;
          end else if (mret_insn_i) begin
            csr_restore_mret_id_o = 1'b1;
            pc_set_o = 1'b1;
            pc_mux_o = PC_ERET;
            instr_id_done_o = 1'b1;
            perf_jump_o = 1'b1;
            ctrl_fsm_ns = DECODE;
          end else if (dret_insn_i) begin
            csr_restore_dret_id_o = 1'b1;
            pc_set_o = 1'b1;
            pc_mux_o = PC_DRET;
            instr_id_done_o = 1'b1;
            ctrl_fsm_ns = DECODE;
          end else if (wfi_insn_i) begin
            instr_id_done_o = 1'b1;
            ctrl_fsm_ns = DECODE;
          end else if (branch_i) begin
            perf_branch_o = 1'b1;
            if (branch_decision_i) begin
              pc_set_o = 1'b1;
              pc_mux_o = PC_JUMP;
              perf_tbranch_o = 1'b1;
              perf_jump_o = 1'b1;
            end
            instr_id_done_o = 1'b1;
          end else if (jump_i) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_JUMP;
            perf_jump_o = 1'b1;
            instr_id_done_o = 1'b1;
          end else begin
            instr_id_done_o = 1'b1;
          end

          if (lsu_load_err_i) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_EXC;
            exc_pc_mux_o = EXC_PC_EXC;
            csr_save_id_o = 1'b1;
            csr_save_cause_o = 1'b1;
            exc_cause_o = 1'b1;
            exc_req_lsu = 1'b1;
            id_exception_o = 1'b1;
            ctrl_fsm_ns = DECODE;
          end
          if (lsu_store_err_i) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_EXC;
            exc_pc_mux_o = EXC_PC_EXC;
            csr_save_id_o = 1'b1;
            csr_save_cause_o = 1'b1;
            exc_cause_o = 1'b0;
            exc_req_lsu = 1'b1;
            id_exception_o = 1'b1;
            ctrl_fsm_ns = DECODE;
          end

          if (irq_pending_i & csr_mstatus_mie_i & ~nmi_mode_q & ~debug_mode_q &
              ~(lsu_req_i & ~lsu_rvalid_i)) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_EXC;
            exc_pc_mux_o = EXC_PC_IRQ;
            csr_save_id_o = 1'b1;
            csr_save_cause_o = 1'b1;
            instr_id_done_o = 1'b1;
            ctrl_fsm_ns = DECODE;
          end

          if (irq_nm_i & ~nmi_mode_q & ~debug_mode_q) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_EXC;
            exc_pc_mux_o = EXC_PC_IRQ;
            csr_save_id_o = 1'b1;
            csr_save_cause_o = 1'b1;
            nmi_mode_d = 1'b1;
            instr_id_done_o = 1'b1;
            ctrl_fsm_ns = DECODE;
          end

          if (debug_req_i & ~debug_mode_q) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_EXC;
            exc_pc_mux_o = EXC_PC_DBD;
            csr_save_id_o = 1'b1;
            debug_csr_save_o = 1'b1;
            debug_cause_o = DBG_CAUSE_HALTREQ;
            debug_mode_d = 1'b1;
            debug_mode_entering_o = 1'b1;
            instr_id_done_o = 1'b1;
            ctrl_fsm_ns = DECODE;
          end
        end
      end

      default: begin
        ctrl_fsm_ns = DECODE;
      end
    endcase
  end

endmodule

module ibex_ex_block #(
  parameter ibex_pkg::rv32m_e RV32M = ibex_pkg::RV32MFast,
  parameter ibex_pkg::rv32b_e RV32B = ibex_pkg::RV32BNone,
  parameter bit BranchTargetALU = 1'b0
) (
  input  logic                clk_i,
  input  logic                rst_ni,

  input  ibex_pkg::alu_op_e   alu_operator_i,
  input  logic [31:0]         alu_operand_a_i,
  input  logic [31:0]         alu_operand_b_i,
  input  logic                alu_instr_first_cycle_i,

  input  logic [31:0]         bt_a_operand_i,
  input  logic [31:0]         bt_b_operand_i,

  input  ibex_pkg::md_op_e    multdiv_operator_i,
  input  logic                mult_en_i,
  input  logic                div_en_i,
  input  logic                mult_sel_i,
  input  logic                div_sel_i,
  input  logic [1:0]          multdiv_signed_mode_i,
  input  logic [31:0]         multdiv_operand_a_i,
  input  logic [31:0]         multdiv_operand_b_i,
  input  logic                multdiv_ready_id_i,
  input  logic                data_ind_timing_i,

  output logic [1:0]          imd_val_we_o,
  output logic [33:0]         imd_val_d_o [2],
  input  logic [33:0]         imd_val_q_i [2],

  output logic [31:0]         alu_adder_result_ex_o,
  output logic [31:0]         result_ex_o,

  output logic [31:0]         branch_target_o,
  output logic                branch_decision_o,

  output logic                ex_valid_o
);
  import ibex_pkg::*;

  logic [31:0] alu_result;
  logic        alu_cmp_result;
  logic [31:0] alu_adder_result;
  logic [31:0] multdiv_result;
  logic        multdiv_valid;
  logic        multdiv_ready;

  ibex_alu #(
    .RV32B(RV32B)
  ) u_alu (
    .operator_i          (alu_operator_i),
    .operand_a_i         (alu_operand_a_i),
    .operand_b_i         (alu_operand_b_i),
    .instr_first_cycle_i (alu_instr_first_cycle_i),
    .result_o            (alu_result),
    .comparison_result_o (alu_cmp_result),
    .adder_result_o      (alu_adder_result)
  );

  assign alu_adder_result_ex_o = alu_adder_result;
  assign branch_decision_o = alu_cmp_result;

  if (BranchTargetALU) begin : gen_branch_target_alu
    logic [31:0] bt_result;
    assign bt_result = bt_a_operand_i + bt_b_operand_i;
    assign branch_target_o = bt_result;
  end else begin : gen_no_branch_target_alu
    assign branch_target_o = alu_adder_result;
  end

  logic [1:0]  imd_val_we;
  logic [33:0] imd_val_d [2];

  assign imd_val_we   = '0;
  assign imd_val_d[0] = '0;
  assign imd_val_d[1] = '0;

  for (genvar i = 0; i < 2; i++) begin : gen_imd_reg
    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        imd_val_q_i[i] <= '0;
      end else if (imd_val_we[i]) begin
        imd_val_q_i[i] <= imd_val_d[i];
      end
    end
  end

  assign imd_val_we_o = imd_val_we;
  assign imd_val_d_o  = imd_val_d;

`ifdef RV32M_RV32MSlow
  ibex_multdiv_slow u_multdiv (
`else
  ibex_multdiv_fast u_multdiv (
`endif
    .clk_i              (clk_i),
    .rst_ni             (rst_ni),
    .mult_en_i          (mult_en_i),
    .div_en_i           (div_en_i),
    .operator_i         (multdiv_operator_i),
    .signed_mode_i      (multdiv_signed_mode_i),
    .op_a_i             (multdiv_operand_a_i),
    .op_b_i             (multdiv_operand_b_i),
    .data_ind_timing_i  (data_ind_timing_i),
    .result_o           (multdiv_result),
    .multdiv_ready_o    (multdiv_ready),
    .multdiv_valid_o    (multdiv_valid)
  );

  always_comb begin
    result_ex_o = alu_result;
    ex_valid_o  = 1'b1;

    if (mult_en_i || div_en_i) begin
      result_ex_o = multdiv_result;
      ex_valid_o  = multdiv_valid;
      if (mult_sel_i || div_sel_i) begin
        result_ex_o = multdiv_result;
        ex_valid_o  = multdiv_valid;
      end
    end
  end

endmodule

module ibex_load_store_unit #(
  parameter bit MemECC = 1'b0,
  parameter int unsigned MemDataWidth = 32
) (
  input  logic                          clk_i,
  input  logic                          rst_ni,

  output logic                          data_req_o,
  input  logic                          data_gnt_i,
  input  logic                          data_rvalid_i,
  input  logic                          data_bus_err_i,
  input  logic                          data_pmp_err_i,

  output logic [31:0]                   data_addr_o,
  output logic                          data_we_o,
  output logic [3:0]                    data_be_o,
  output logic [MemDataWidth-1:0]       data_wdata_o,
  input  logic [MemDataWidth-1:0]       data_rdata_i,

  input  logic                          lsu_we_i,
  input  logic [1:0]                    lsu_type_i,
  input  logic [31:0]                   lsu_wdata_i,
  input  logic                          lsu_sign_ext_i,

  output logic [31:0]                   lsu_rdata_o,
  output logic                          lsu_rdata_valid_o,
  input  logic                          lsu_req_i,
  output logic                          lsu_req_done_o,

  input  logic [31:0]                   adder_result_ex_i,

  output logic                          addr_incr_req_o,
  output logic [31:0]                   addr_last_o,

  output logic                          lsu_resp_valid_o,

  output logic                          load_err_o,
  output logic                          load_resp_intg_err_o,
  output logic                          store_err_o,
  output logic                          store_resp_intg_err_o,

  output logic                          busy_o,

  output logic                          perf_load_o,
  output logic                          perf_store_o
);
  logic [31:0] data_addr;
  logic [31:0] data_addr_aligned;
  logic [3:0]  data_be;
  logic [31:0] rdata_shifted;
  logic        split_misaligned;
  logic        addr_incr_req_q;
  logic [31:0] addr_last_q;
  logic        req_pending_q;
  logic        is_load;

  assign data_addr = adder_result_ex_i;
  assign data_addr_aligned = {data_addr[31:2], 2'b00};

  always_comb begin
    data_be = 4'b1111;
    unique case (lsu_type_i)
      2'b00:   data_be = 4'b1111;
      2'b01:   data_be = (data_addr[1]) ? 4'b1100 : 4'b0011;
      2'b10:   data_be = 4'b0001 << data_addr[1:0];
      default: data_be = 4'b1111;
    endcase
  end

  assign split_misaligned = 1'b0;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      req_pending_q   <= 1'b0;
      addr_incr_req_q <= 1'b0;
      addr_last_q     <= '0;
      is_load         <= 1'b0;
    end else begin
      addr_incr_req_q <= 1'b0;
      if (lsu_req_i && !data_pmp_err_i) begin
        req_pending_q <= 1'b1;
        is_load       <= ~lsu_we_i;
        addr_last_q   <= data_addr;
      end else if (data_rvalid_i) begin
        req_pending_q <= 1'b0;
      end
    end
  end

  assign data_req_o   = lsu_req_i & ~req_pending_q & ~data_pmp_err_i;
  assign data_addr_o  = data_addr_aligned;
  assign data_we_o    = lsu_we_i;
  assign data_be_o    = data_be;

  always_comb begin
    data_wdata_o = lsu_wdata_i;
    unique case (lsu_type_i)
      2'b01: begin
        if (data_addr[1])
          data_wdata_o = {16'b0, lsu_wdata_i[15:0]};
        else
          data_wdata_o = {lsu_wdata_i[15:0], 16'b0};
      end
      2'b10: begin
        case (data_addr[1:0])
          2'b00: data_wdata_o = {24'b0, lsu_wdata_i[7:0]};
          2'b01: data_wdata_o = {16'b0, lsu_wdata_i[7:0], 8'b0};
          2'b10: data_wdata_o = {8'b0, lsu_wdata_i[7:0], 16'b0};
          2'b11: data_wdata_o = {lsu_wdata_i[7:0], 24'b0};
        endcase
      end
      default: data_wdata_o = lsu_wdata_i;
    endcase
  end

  always_comb begin
    rdata_shifted = data_rdata_i[31:0];
    unique case (lsu_type_i)
      2'b01: begin
        if (addr_last_q[1])
          rdata_shifted = {16'b0, data_rdata_i[31:16]};
        else
          rdata_shifted = {16'b0, data_rdata_i[15:0]};
      end
      2'b10: begin
        case (addr_last_q[1:0])
          2'b00: rdata_shifted = {24'b0, data_rdata_i[7:0]};
          2'b01: rdata_shifted = {24'b0, data_rdata_i[15:8]};
          2'b10: rdata_shifted = {24'b0, data_rdata_i[23:16]};
          2'b11: rdata_shifted = {24'b0, data_rdata_i[31:24]};
        endcase
      end
      default: rdata_shifted = data_rdata_i[31:0];
    endcase
  end

  logic [31:0] lsu_rdata_ext;
  always_comb begin
    lsu_rdata_ext = rdata_shifted;
    if (lsu_sign_ext_i) begin
      unique case (lsu_type_i)
        2'b01: lsu_rdata_ext = {{16{rdata_shifted[15]}}, rdata_shifted[15:0]};
        2'b10: lsu_rdata_ext = {{24{rdata_shifted[7]}}, rdata_shifted[7:0]};
        default: ;
      endcase
    end
  end

  assign lsu_rdata_o       = lsu_rdata_ext;
  assign lsu_rdata_valid_o = data_rvalid_i & req_pending_q & is_load;
  assign lsu_req_done_o    = lsu_req_i & (data_gnt_i | data_pmp_err_i);

  assign lsu_resp_valid_o  = data_rvalid_i & req_pending_q;
  assign load_err_o        = data_rvalid_i & req_pending_q & is_load & data_bus_err_i;
  assign store_err_o       = data_rvalid_i & req_pending_q & ~is_load & data_bus_err_i;
  assign load_resp_intg_err_o = 1'b0;
  assign store_resp_intg_err_o = 1'b0;

  assign addr_incr_req_o = 1'b0;
  assign addr_last_o = addr_last_q;

  assign busy_o = req_pending_q;

  assign perf_load_o  = lsu_rdata_valid_o;
  assign perf_store_o = data_req_o & lsu_we_i;

endmodule

module ibex_wb_stage #(
  parameter bit ResetAll = 1'b0,
  parameter bit WritebackStage = 1'b0,
  parameter bit DummyInstructions = 1'b0
) (
  input  logic                clk_i,
  input  logic                rst_ni,

  input  logic                en_wb_i,
  input  ibex_pkg::wb_instr_type_e instr_type_wb_i,
  input  logic [31:0]         pc_id_i,
  input  logic                instr_is_compressed_id_i,
  input  logic                instr_perf_count_id_i,

  output logic                ready_wb_o,
  output logic                rf_write_wb_o,
  output logic                outstanding_load_wb_o,
  output logic                outstanding_store_wb_o,
  output logic [31:0]         pc_wb_o,
  output logic                perf_instr_ret_wb_o,
  output logic                perf_instr_ret_compressed_wb_o,
  output logic                perf_instr_ret_wb_spec_o,
  output logic                perf_instr_ret_compressed_wb_spec_o,

  input  logic [4:0]          rf_waddr_id_i,
  input  logic [31:0]         rf_wdata_id_i,
  input  logic                rf_we_id_i,

  input  logic                dummy_instr_id_i,

  input  logic [31:0]         rf_wdata_lsu_i,
  input  logic                rf_we_lsu_i,

  output logic [31:0]         rf_wdata_fwd_wb_o,

  output logic [4:0]          rf_waddr_wb_o,
  output logic [31:0]         rf_wdata_wb_o,
  output logic                rf_we_wb_o,

  output logic                dummy_instr_wb_o,

  input  logic                lsu_resp_valid_i,
  input  logic                lsu_resp_err_i,

  output logic                instr_done_wb_o
);
  import ibex_pkg::*;

  if (WritebackStage) begin : gen_wb_stage
    logic [31:0] rf_wdata_wb_q;
    logic [4:0]  rf_waddr_wb_q;
    logic        rf_we_wb_q;
    logic        wb_valid_q;
    logic        outstanding_load_q, outstanding_store_q;
    logic        rf_we_wb_next;

    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        rf_wdata_wb_q     <= '0;
        rf_waddr_wb_q     <= '0;
        rf_we_wb_q        <= 1'b0;
        wb_valid_q        <= 1'b0;
        outstanding_load_q  <= 1'b0;
        outstanding_store_q <= 1'b0;
      end else begin
        if (en_wb_i && ready_wb_o) begin
          rf_waddr_wb_q <= rf_waddr_id_i;
          rf_we_wb_q   <= rf_we_id_i;
          wb_valid_q   <= 1'b1;
          outstanding_load_q  <= (instr_type_wb_i == WB_INSTR_LOAD);
          outstanding_store_q <= (instr_type_wb_i == WB_INSTR_STORE);
          if (instr_type_wb_i == WB_INSTR_LOAD) begin
            rf_wdata_wb_q <= '0;
          end else begin
            rf_wdata_wb_q <= rf_wdata_id_i;
          end
        end else if (lsu_resp_valid_i || !wb_valid_q) begin
          wb_valid_q <= 1'b0;
          rf_we_wb_q <= 1'b0;
        end
      end
    end

    assign rf_we_wb_next = rf_we_wb_q | (lsu_resp_valid_i & outstanding_load_q);
    assign rf_wdata_fwd_wb_o = (outstanding_load_q & lsu_resp_valid_i) ? rf_wdata_lsu_i : rf_wdata_wb_q;

    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        rf_wdata_wb_o <= '0;
      end else if (lsu_resp_valid_i & outstanding_load_q) begin
        rf_wdata_wb_o <= rf_wdata_lsu_i;
      end else if (wb_valid_q) begin
        rf_wdata_wb_o <= rf_wdata_wb_q;
      end
    end

    assign rf_waddr_wb_o = rf_waddr_wb_q;
    assign rf_we_wb_o    = rf_we_wb_next;
    assign ready_wb_o    = ~wb_valid_q | (lsu_resp_valid_i & outstanding_load_q) |
                           (~outstanding_load_q & ~outstanding_store_q);

    assign outstanding_load_wb_o  = outstanding_load_q;
    assign outstanding_store_wb_o = outstanding_store_q;
    assign pc_wb_o = pc_id_i;

    assign perf_instr_ret_wb_o = wb_valid_q & ~outstanding_load_q & ~outstanding_store_q;
    assign perf_instr_ret_compressed_wb_o = perf_instr_ret_wb_o & instr_is_compressed_id_i;
    assign perf_instr_ret_wb_spec_o = perf_instr_ret_wb_o;
    assign perf_instr_ret_compressed_wb_spec_o = perf_instr_ret_compressed_wb_o;

    assign instr_done_wb_o = wb_valid_q & ~outstanding_load_q & ~outstanding_store_q & ~lsu_resp_err_i;
    assign rf_write_wb_o = rf_we_wb_next;
    assign dummy_instr_wb_o = dummy_instr_id_i;

  end else begin : gen_no_wb_stage
    assign rf_wdata_fwd_wb_o = rf_wdata_id_i;
    assign rf_waddr_wb_o     = rf_waddr_id_i;
    assign rf_wdata_wb_o     = rf_we_lsu_i ? rf_wdata_lsu_i : rf_wdata_id_i;
    assign rf_we_wb_o        = rf_we_id_i | rf_we_lsu_i;
    assign ready_wb_o        = 1'b1;

    assign outstanding_load_wb_o  = 1'b0;
    assign outstanding_store_wb_o = 1'b0;
    assign pc_wb_o = pc_id_i;

    assign perf_instr_ret_wb_o = en_wb_i;
    assign perf_instr_ret_compressed_wb_o = perf_instr_ret_wb_o & instr_is_compressed_id_i;
    assign perf_instr_ret_wb_spec_o = perf_instr_ret_wb_o;
    assign perf_instr_ret_compressed_wb_spec_o = perf_instr_ret_compressed_wb_o;

    assign instr_done_wb_o = en_wb_i;
    assign rf_write_wb_o = rf_we_wb_o;
    assign dummy_instr_wb_o = dummy_instr_id_i;
  end

endmodule

module ibex_pmp #(
  parameter int unsigned DmBaseAddr = 32'h1A110000,
  parameter int unsigned DmAddrMask = 32'h00000FFF,
  parameter int unsigned PMPGranularity = 0,
  parameter int unsigned PMPNumChan = 3,
  parameter int unsigned PMPNumRegions = 4
) (
  input  logic [PMP_ADDR_MSB:0] csr_pmp_addr_i [PMPNumRegions],
  input  ibex_pkg::pmp_cfg_t    csr_pmp_cfg_i  [PMPNumRegions],
  input  ibex_pkg::pmp_mseccfg_t csr_pmp_mseccfg_i,
  input  logic                  debug_mode_i,
  input  ibex_pkg::priv_lvl_e   priv_mode_i [PMPNumChan],

  input  logic [PMP_ADDR_MSB:0] pmp_req_addr_i [PMPNumChan],
  input  ibex_pkg::pmp_req_e    pmp_req_type_i [PMPNumChan],
  output logic                  pmp_req_err_o  [PMPNumChan]
);
  import ibex_pkg::*;

  logic [PMPNumRegions-1:0] region_match_all [PMPNumChan];

  for (genvar c = 0; c < PMPNumChan; c++) begin : gen_chan
    logic [PMPNumRegions-1:0] region_match;
    logic [PMPNumRegions-1:0] region_perm_check;
    logic                      region_err;

    for (genvar r = 0; r < PMPNumRegions; r++) begin : gen_region
      logic [PMP_ADDR_MSB:0] region_base;
      logic [PMP_ADDR_MSB:0] region_mask;
      logic                  match;
      logic                  perm_ok;

      logic [1:0] cfg_mode;
      logic       cfg_r, cfg_w, cfg_x, cfg_lock;

      assign cfg_mode = csr_pmp_cfg_i[r].a;
      assign cfg_lock = csr_pmp_cfg_i[r].l;
      assign cfg_r = 1'b0;
      assign cfg_w = 1'b0;
      assign cfg_x = 1'b0;

      assign region_base = {csr_pmp_addr_i[r], 2'b00};

      if (PMPGranularity == 0) begin : gen_g0
        always_comb begin
          unique case (cfg_mode)
            2'b00: match = 1'b0;
            2'b01: match = (pmp_req_addr_i[c][PMP_ADDR_MSB:2] == csr_pmp_addr_i[r][PMP_ADDR_MSB-2:0]);
            2'b10: begin
              logic [PMP_ADDR_MSB:0] region_top;
              region_top = {csr_pmp_addr_i[r], 2'b11};
              if (r < PMPNumRegions - 1) begin
                logic [PMP_ADDR_MSB:0] next_base;
                next_base = {csr_pmp_addr_i[r+1], 2'b00};
                match = (pmp_req_addr_i[c] >= region_base) && (pmp_req_addr_i[c] < next_base);
              end else begin
                match = (pmp_req_addr_i[c] >= region_base);
              end
            end
            2'b11: begin
              logic [33:0] mask;
              logic [4:0] leading_ones;
              leading_ones = '0;
              for (int k = PMP_ADDR_MSB - 2; k >= 0; k--) begin
                if (csr_pmp_addr_i[r][k]) leading_ones = leading_ones + 1;
                else break;
              end
              mask = {{(34-leading_ones){1'b0}}, {leading_ones{1'b1}}, 2'b00};
              match = ((pmp_req_addr_i[c] & mask) == (region_base & mask));
            end
            default: match = 1'b0;
          endcase
        end
      end else begin : gen_gN
        always_comb begin
          unique case (cfg_mode)
            2'b00: match = 1'b0;
            2'b01: match = (pmp_req_addr_i[c][PMP_ADDR_MSB:PMPGranularity+2] ==
                             csr_pmp_addr_i[r][PMP_ADDR_MSB-2:PMPGranularity]);
            2'b10: begin
              if (r < PMPNumRegions - 1) begin
                match = (pmp_req_addr_i[c] >= region_base) &&
                        (pmp_req_addr_i[c] < {csr_pmp_addr_i[r+1], 2'b00});
              end else begin
                match = (pmp_req_addr_i[c] >= region_base);
              end
            end
            2'b11: begin
              logic [33:0] mask;
              logic [4:0] leading_ones;
              leading_ones = '0;
              for (int k = PMP_ADDR_MSB - 2; k >= 0; k--) begin
                if (csr_pmp_addr_i[r][k]) leading_ones = leading_ones + 1;
                else break;
              end
              mask = {{(34-leading_ones){1'b0}}, {leading_ones{1'b1}}, 2'b00};
              match = ((pmp_req_addr_i[c] & mask) == (region_base & mask));
            end
            default: match = 1'b0;
          endcase
        end
      end

      assign region_match[r] = match & (cfg_mode != 2'b00);

      always_comb begin
        perm_ok = 1'b1;
        if (cfg_lock || priv_mode_i[c] != PRIV_LVL_M) begin
          unique case (pmp_req_type_i[c])
            PMP_ACC_EXEC:  perm_ok = cfg_x;
            PMP_ACC_WRITE: perm_ok = cfg_w;
            PMP_ACC_READ:  perm_ok = cfg_r;
            default:       perm_ok = 1'b1;
          endcase
        end
        if (debug_mode_i) perm_ok = 1'b1;
      end

      assign region_perm_check[r] = region_match[r] & ~perm_ok;
    end

    assign region_match_all[c] = region_match;
    assign region_err = |region_perm_check;
    assign pmp_req_err_o[c] = region_err;
  end

endmodule

