    CSR_PMPADDR3   = 12'h3B3,
    CSR_PMPADDR4   = 12'h3B4,
    CSR_PMPADDR5   = 12'h3B5,
    CSR_PMPADDR6   = 12'h3B6,
    CSR_PMPADDR7   = 12'h3B7,
    CSR_PMPADDR8   = 12'h3B8,
    CSR_PMPADDR9   = 12'h3B9,
    CSR_PMPADDR10  = 12'h3BA,
    CSR_PMPADDR11  = 12'h3BB,
    CSR_PMPADDR12  = 12'h3BC,
    CSR_PMPADDR13  = 12'h3BD,
    CSR_PMPADDR14  = 12'h3BE,
    CSR_PMPADDR15  = 12'h3BF,
    CSR_MCYCLE     = 12'hB00,
    CSR_MINSTRET   = 12'hB02,
    CSR_MCYCLEH    = 12'hB80,
    CSR_MINSTRETH  = 12'hB82,
    CSR_CPUCTRLSTS = 12'h7C0,
    CSR_DCSR       = 12'h7B0,
    CSR_DPC        = 12'h7B1,
    CSR_DSCRATCH0  = 12'h7B2,
    CSR_DSCRATCH1  = 12'h7B3
  } csr_num_e;

endpackage

module ibex_cs_registers #(
  parameter bit DbgTriggerEn = 1'b0,
  parameter int unsigned DbgHwBreakNum = 1,
  parameter bit DataIndTiming = 1'b0,
  parameter bit DummyInstructions = 1'b0,
  parameter bit ShadowCSR = 1'b0,
  parameter bit ICache = 1'b0,
  parameter int unsigned MHPMCounterNum = 0,
  parameter int unsigned MHPMCounterWidth = 40,
  parameter bit PMPEnable = 1'b0,
  parameter int unsigned PMPGranularity = 0,
  parameter int unsigned PMPNumRegions = 4,
  parameter ibex_pkg::pmp_cfg_t PMPRstCfg[ibex_pkg::PMP_MAX_REGIONS] = ibex_pkg::PmpCfgRst,
  parameter logic [ibex_pkg::PMP_ADDR_MSB:0] PMPRstAddr[ibex_pkg::PMP_MAX_REGIONS] = ibex_pkg::PmpAddrRst,
  parameter ibex_pkg::pmp_mseccfg_t PMPRstMsecCfg = ibex_pkg::PmpMseccfgRst,
  parameter bit RV32E = 1'b0,
  parameter ibex_pkg::rv32m_e RV32M = ibex_pkg::RV32MFast,
  parameter ibex_pkg::rv32b_e RV32B = ibex_pkg::RV32BNone,
  parameter logic [31:0] CsrMvendorId = 32'b0,
  parameter logic [31:0] CsrMimpId = 32'b0
) (
  input  logic                clk_i,
  input  logic                rst_ni,

  input  logic [31:0]         hart_id_i,
  output ibex_pkg::priv_lvl_e priv_mode_id_o,
  output ibex_pkg::priv_lvl_e priv_mode_lsu_o,

  output logic [31:0]         csr_mtvec_o,
  input  logic                csr_mtvec_init_i,
  input  logic [31:0]         boot_addr_i,

  input  logic                csr_access_i,
  input  logic [11:0]         csr_addr_i,
  input  logic [31:0]         csr_wdata_i,
  input  ibex_pkg::csr_op_e   csr_op_i,
  input  logic                csr_op_en_i,
  output logic [31:0]         csr_rdata_o,

  input  logic                irq_software_i,
  input  logic                irq_timer_i,
  input  logic                irq_external_i,
  input  logic [14:0]         irq_fast_i,
  input  logic                nmi_mode_i,
  output logic                irq_pending_o,
  output ibex_pkg::irqs_t     irqs_o,
  output logic                csr_mstatus_mie_o,
  output logic                csr_mstatus_tw_o,
  output logic [31:0]         csr_mepc_o,
  output logic [31:0]         csr_mtval_o,

  output ibex_pkg::pmp_cfg_t  csr_pmp_cfg_o [PMPNumRegions],
  output logic [ibex_pkg::PMP_ADDR_MSB:0] csr_pmp_addr_o [PMPNumRegions],
  output ibex_pkg::pmp_mseccfg_t csr_pmp_mseccfg_o,

  output logic [31:0]         csr_depc_o,
  input  logic                debug_mode_i,
  input  logic                debug_mode_entering_i,
  input  ibex_pkg::dbg_cause_e debug_cause_i,
  input  logic                debug_csr_save_i,
  output logic                debug_single_step_o,
  output logic                debug_ebreakm_o,
  output logic                debug_ebreaku_o,
  output logic                trigger_match_o,

  input  logic [31:0]         pc_if_i,
  input  logic [31:0]         pc_id_i,
  input  logic [31:0]         pc_wb_i,

  output logic                data_ind_timing_o,
  output logic                dummy_instr_en_o,
  output logic [2:0]          dummy_instr_mask_o,
  output logic                dummy_instr_seed_en_o,
  output logic [31:0]         dummy_instr_seed_o,
  output logic                icache_enable_o,
  output logic                csr_shadow_err_o,
  input  logic                ic_scr_key_valid_i,

  input  logic                csr_save_if_i,
  input  logic                csr_save_id_i,
  input  logic                csr_save_wb_i,
  input  logic                csr_restore_mret_i,
  input  logic                csr_restore_dret_i,
  input  logic                csr_save_cause_i,
  input  ibex_pkg::exc_cause_t csr_mcause_i,
  input  logic [31:0]         csr_mtval_i,
  output logic                illegal_csr_insn_o,

  output logic                double_fault_seen_o,

  input  logic                instr_ret_i,
  input  logic                instr_ret_compressed_i,
  input  logic                instr_ret_spec_i,
  input  logic                instr_ret_compressed_spec_i,
  input  logic                iside_wait_i,
  input  logic                jump_i,
  input  logic                branch_i,
  input  logic                branch_taken_i,
  input  logic                mem_load_i,
  input  logic                mem_store_i,
  input  logic                dside_wait_i,
  input  logic                mul_wait_i,
  input  logic                div_wait_i
);
  import ibex_pkg::*;

  logic [31:0] mstatus_q, mstatus_d;
  logic [31:0] mie_q, mie_d;
  logic [31:0] mtvec_q, mtvec_d;
  logic [31:0] mscratch_q, mscratch_d;
  logic [31:0] mepc_q, mepc_d;
  logic [31:0] mcause_q, mcause_d;
  logic [31:0] mtval_q, mtval_d;
  logic [31:0] mip_d, mip_q;
  logic [31:0] mcountinhibit_q, mcountinhibit_d;
  logic [63:0] mcycle_q, mcycle_d;
  logic [63:0] minstret_q, minstret_d;
  logic [31:0] cpuctrlsts_q, cpuctrlsts_d;
  logic [31:0] dcsr_q, dcsr_d;
  logic [31:0] dpc_q, dpc_d;
  logic [31:0] dscratch0_q, dscratch0_d;

  pmp_cfg_t pmp_cfg_q [PMPNumRegions];
  pmp_cfg_t pmp_cfg_d [PMPNumRegions];
  logic [PMP_ADDR_MSB:0] pmp_addr_q [PMPNumRegions];
  logic [PMP_ADDR_MSB:0] pmp_addr_d [PMPNumRegions];
  pmp_mseccfg_t pmp_mseccfg_q, pmp_mseccfg_d;

  logic [63:0] mhpmcounter [14];
  logic [31:0] mhpmevent [14];

  logic [31:0] csr_wdata_int;
  logic [31:0] csr_rdata_int;
  logic        csr_wr;
  logic        illegal_csr;

  assign priv_mode_id_o = PRIV_LVL_M;
  assign priv_mode_lsu_o = PRIV_LVL_M;

  always_comb begin
    csr_wdata_int = csr_wdata_i;
    unique case (csr_op_i)
      CSR_OP_WRITE: csr_wdata_int = csr_wdata_i;
      CSR_OP_SET:   csr_wdata_int = csr_rdata_int | csr_wdata_i;
      CSR_OP_CLEAR: csr_wdata_int = csr_rdata_int & ~csr_wdata_i;
      default:      csr_wdata_int = csr_wdata_i;
    endcase
  end

  assign mip_d = mip_q;
  always_comb begin
    mip_d[CSR_MSIX_BIT] = irq_software_i;
    mip_d[CSR_MTIX_BIT] = irq_timer_i;
    mip_d[CSR_MEIX_BIT] = irq_external_i;
    mip_d[CSR_MFIX_BIT_HIGH:CSR_MFIX_BIT_LOW] = irq_fast_i;
  end

  assign irqs_o.irq_software = irq_software_i & mie_q[CSR_MSIX_BIT];
  assign irqs_o.irq_timer    = irq_timer_i    & mie_q[CSR_MTIX_BIT];
  assign irqs_o.irq_external = irq_external_i & mie_q[CSR_MEIX_BIT];
  assign irqs_o.irq_fast     = irq_fast_i & mie_q[CSR_MFIX_BIT_HIGH:CSR_MFIX_BIT_LOW];

  assign irq_pending_o = |{irqs_o.irq_software, irqs_o.irq_timer, irqs_o.irq_external, irqs_o.irq_fast};

  assign csr_mstatus_mie_o = mstatus_q[3];
  assign csr_mstatus_tw_o  = mstatus_q[21];

  always_comb begin
    mstatus_d = mstatus_q;
    if (csr_save_cause_i) begin
      mstatus_d[7]   = mstatus_q[3];
      mstatus_d[12:11] = {PRIV_LVL_M};
      mstatus_d[3]   = 1'b0;
    end
    if (csr_restore_mret_i) begin
      mstatus_d[3]   = mstatus_q[7];
      mstatus_d[7]   = 1'b1;
      mstatus_d[12:11] = {PRIV_LVL_M};
    end
    if (csr_restore_dret_i) begin
      mstatus_d[3]   = mstatus_q[7];
      mstatus_d[7]   = 1'b1;
    end
  end

  always_comb begin
    mepc_d = mepc_q;
    if (csr_save_if_i) mepc_d = pc_if_i & ~32'b1;
    if (csr_save_id_i) mepc_d = pc_id_i & ~32'b1;
    if (csr_save_wb_i) mepc_d = pc_wb_i & ~32'b1;
  end

  always_comb begin
    mcause_d = mcause_q;
    if (csr_save_cause_i) mcause_d = {csr_mcause_i.irq, 25'b0, csr_mcause_i.cause};
  end

  always_comb begin
    mtval_d = mtval_q;
    if (csr_save_cause_i) mtval_d = csr_mtval_i;
  end

  always_comb begin
    mtvec_d = mtvec_q;
    if (csr_mtvec_init_i) begin
      mtvec_d = {boot_addr_i[31:2], 2'b00} | {csr_wdata_int[31:2], 2'b00};
    end
  end

  always_comb begin
    mcycle_d = mcycle_q;
    if (!mcountinhibit_q[0]) mcycle_d = mcycle_q + 64'd1;
  end

  always_comb begin
    minstret_d = minstret_q;
    if (!mcountinhibit_q[2] && instr_ret_i) minstret_d = minstret_q + 64'd1;
  end

  always_comb begin
    cpuctrlsts_d = cpuctrlsts_q;
    if (ICache) cpuctrlsts_d[0] = cpuctrlsts_q[0];
    if (DataIndTiming) cpuctrlsts_d[1] = cpuctrlsts_q[1];
    if (DummyInstructions) begin
      cpuctrlsts_d[2] = cpuctrlsts_q[2];
      cpuctrlsts_d[19:16] = cpuctrlsts_q[19:16];
    end
  end

  always_comb begin
    dcsr_d = dcsr_q;
    if (debug_csr_save_i) begin
      dcsr_d[31:28] = 4'h4;
      dcsr_d[2]     = 1'b1;
      dcsr_d[6:4]   = debug_cause_i;
      dcsr_d[1]     = priv_mode_id_o == PRIV_LVL_M;
    end
  end

  always_comb begin
    dpc_d = dpc_q;
    if (debug_csr_save_i) begin
      if (csr_save_if_i) dpc_d = pc_if_i;
      else if (csr_save_id_i) dpc_d = pc_id_i;
      else dpc_d = pc_wb_i;
    end
  end

  always_comb begin
    dscratch0_d = dscratch0_q;
  end

  for (genvar r = 0; r < PMPNumRegions; r++) begin : gen_pmp
    always_comb begin
      pmp_cfg_d[r] = pmp_cfg_q[r];
      pmp_addr_d[r] = pmp_addr_q[r];
    end
    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        pmp_cfg_q[r] <= PMPRstCfg[r];
        pmp_addr_q[r] <= PMPRstAddr[r];
      end else begin
        pmp_cfg_q[r] <= pmp_cfg_d[r];
        pmp_addr_q[r] <= pmp_addr_d[r];
      end
    end
    assign csr_pmp_cfg_o[r] = pmp_cfg_q[r];
    assign csr_pmp_addr_o[r] = pmp_addr_q[r];
  end
  assign csr_pmp_mseccfg_o = pmp_mseccfg_q;

  always_comb begin
    illegal_csr = 1'b0;
    csr_rdata_int = '0;
    csr_wr = csr_op_en_i;

    unique case (csr_addr_i)
      CSR_MSTATUS: begin
        csr_rdata_int = mstatus_q;
      end
      CSR_MISA: begin
        csr_rdata_int = {CSR_MISA_MXL, 4'b0, 12'b0, 12'b0,
                         (RV32M != RV32MNone), 1'b0, 1'b0, 1'b1, 1'b0, 1'b0, 1'b1, 1'b1, 1'b0};
      end
      CSR_MIE: begin
        csr_rdata_int = mie_q;
      end
      CSR_MTVEC: begin
        csr_rdata_int = mtvec_q;
      end
      CSR_MCOUNTINHIBIT: begin
        csr_rdata_int = mcountinhibit_q;
      end
      CSR_MSCRATCH: begin
        csr_rdata_int = mscratch_q;
      end
      CSR_MEPC: begin
        csr_rdata_int = mepc_q;
      end
      CSR_MCAUSE: begin
        csr_rdata_int = mcause_q;
      end
      CSR_MTVAL: begin
        csr_rdata_int = mtval_q;
      end
      CSR_MIP: begin
        csr_rdata_int = mip_q;
        csr_wr = 1'b0;
      end
      CSR_MCYCLE: begin
        csr_rdata_int = mcycle_q[31:0];
      end
      CSR_MCYCLEH: begin
        csr_rdata_int = mcycle_q[63:32];
      end
      CSR_MINSTRET: begin
        csr_rdata_int = minstret_q[31:0];
      end
      CSR_MINSTRETH: begin
        csr_rdata_int = minstret_q[63:32];
      end
      CSR_CPUCTRLSTS: begin
        csr_rdata_int = cpuctrlsts_q;
      end
      CSR_DCSR: begin
        if (debug_mode_i) csr_rdata_int = dcsr_q;
        else illegal_csr = 1'b1;
      end
      CSR_DPC: begin
        if (debug_mode_i) csr_rdata_int = dpc_q;
        else illegal_csr = 1'b1;
      end
      CSR_DSCRATCH0: begin
        if (debug_mode_i) csr_rdata_int = dscratch0_q;
        else illegal_csr = 1'b1;
      end
      default: begin
        if (PMPEnable) begin
          if (csr_addr_i >= CSR_PMPCFG0 && csr_addr_i <= CSR_PMPCFG3) begin
            logic [1:0] cfg_idx;
            cfg_idx = csr_addr_i[1:0];
            logic [31:0] cfg_val;
            cfg_val = '0;
            for (int r = 0; r < 4; r++) begin
              if (cfg_idx * 4 + r < PMPNumRegions) begin
                cfg_val[r*8+:8] = pmp_cfg_q[cfg_idx*4+r];
              end
            end
            csr_rdata_int = cfg_val;
          end else if (csr_addr_i >= CSR_PMPADDR0 && csr_addr_i <= CSR_PMPADDR15) begin
            logic [3:0] addr_idx;
            addr_idx = csr_addr_i[3:0];
            if (addr_idx < PMPNumRegions) begin
              csr_rdata_int = {pmp_addr_q[addr_idx][PMP_ADDR_MSB:2], 2'b00};
            end else begin
              illegal_csr = 1'b1;
            end
          end else begin
            illegal_csr = 1'b1;
          end
        end else begin
          illegal_csr = 1'b1;
        end
      end
    endcase
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mstatus_q       <= 32'h00001800;
      mie_q           <= '0;
      mtvec_q         <= '0;
      mscratch_q      <= '0;
      mepc_q          <= '0;
      mcause_q        <= '0;
      mtval_q         <= '0;
      mip_q           <= '0;
      mcountinhibit_q <= '0;
      mcycle_q        <= '0;
      minstret_q      <= '0;
      cpuctrlsts_q    <= '0;
      dcsr_q          <= 32'h00000040;
      dpc_q           <= '0;
      dscratch0_q     <= '0;
      pmp_mseccfg_q   <= PmpMseccfgRst;
    end else begin
      mcycle_q   <= mcycle_d;
      minstret_q <= minstret_d;
      mip_q      <= mip_d;
      mstatus_d  = mstatus_q;
      mepc_d     = mepc_q;
      mcause_d   = mcause_q;
      mtval_d    = mtval_q;
      mtvec_d    = mtvec_q;

      if (csr_save_cause_i) begin
        mstatus_d[7]   = mstatus_q[3];
        mstatus_d[12:11] = {PRIV_LVL_M};
        mstatus_d[3]   = 1'b0;
        mcause_d = {csr_mcause_i.irq, 25'b0, csr_mcause_i.cause};
        mtval_d  = csr_mtval_i;
      end
      if (csr_restore_mret_i) begin
        mstatus_d[3]   = mstatus_q[7];
        mstatus_d[7]   = 1'b1;
        mstatus_d[12:11] = {PRIV_LVL_M};
      end
      if (csr_restore_dret_i) begin
        mstatus_d[3]   = mstatus_q[7];
        mstatus_d[7]   = 1'b1;
      end
      if (csr_save_if_i) mepc_d = pc_if_i & ~32'b1;
      if (csr_save_id_i) mepc_d = pc_id_i & ~32'b1;
      if (csr_save_wb_i) mepc_d = pc_wb_i & ~32'b1;
      if (csr_mtvec_init_i) mtvec_d = {boot_addr_i[31:2], 2'b00};

      mstatus_q  <= mstatus_d;
      mie_q      <= mie_d;
      mtvec_q    <= mtvec_d;
      mscratch_q <= mscratch_d;
      mepc_q     <= mepc_d;
      mcause_q   <= mcause_d;
      mtval_q    <= mtval_d;
      mcountinhibit_q <= mcountinhibit_d;
      cpuctrlsts_q    <= cpuctrlsts_d;
      dcsr_q     <= dcsr_d;
      dpc_q      <= dpc_d;
      dscratch0_q <= dscratch0_d;
      pmp_mseccfg_q <= pmp_mseccfg_d;

      if (csr_wr && !illegal_csr) begin
        unique case (csr_addr_i)
          CSR_MSTATUS: mstatus_q <= csr_wdata_int & 32'h00088900;
          CSR_MIE: mie_q <= csr_wdata_int & 32'hFFFF0888;
          CSR_MTVEC: mtvec_q <= {csr_wdata_int[31:2], 2'b00};
          CSR_MCOUNTINHIBIT: mcountinhibit_q <= csr_wdata_int;
          CSR_MSCRATCH: mscratch_q <= csr_wdata_int;
          CSR_MEPC: mepc_q <= csr_wdata_int & ~32'b1;
          CSR_MCAUSE: mcause_q <= csr_wdata_int;
          CSR_MTVAL: mtval_q <= csr_wdata_int;
          CSR_CPUCTRLSTS: cpuctrlsts_q <= csr_wdata_int & 32'h000F0007;
          CSR_DCSR: if (debug_mode_i) dcsr_q <= csr_wdata_int;
          CSR_DPC: if (debug_mode_i) dpc_q <= csr_wdata_int & ~32'b1;
          CSR_DSCRATCH0: if (debug_mode_i) dscratch0_q <= csr_wdata_int;
          CSR_MCYCLE: mcycle_q[31:0] <= csr_wdata_int;
          CSR_MCYCLEH: mcycle_q[63:32] <= csr_wdata_int;
          CSR_MINSTRET: minstret_q[31:0] <= csr_wdata_int;
          CSR_MINSTRETH: minstret_q[63:32] <= csr_wdata_int;
          default: begin
            if (PMPEnable) begin
              if (csr_addr_i >= CSR_PMPCFG0 && csr_addr_i <= CSR_PMPCFG3) begin
                logic [1:0] cfg_idx;
                cfg_idx = csr_addr_i[1:0];
                for (int r = 0; r < 4; r++) begin
                  if (cfg_idx * 4 + r < PMPNumRegions && !pmp_cfg_q[cfg_idx*4+r].l) begin
                    pmp_cfg_q[cfg_idx*4+r] <= csr_wdata_int[r*8+:8];
                  end
                end
              end else if (csr_addr_i >= CSR_PMPADDR0 && csr_addr_i <= CSR_PMPADDR15) begin
                logic [3:0] addr_idx;
                addr_idx = csr_addr_i[3:0];
                if (addr_idx < PMPNumRegions && !pmp_cfg_q[addr_idx].l) begin
                  pmp_addr_q[addr_idx] <= {csr_wdata_int[PMP_ADDR_MSB-2:0], 2'b00};
                end
              end
            end
          end
        endcase
      end

      if (debug_csr_save_i) begin
        dcsr_q[31:28] <= 4'h4;
        dcsr_q[2] <= 1'b1;
        dcsr_q[6:4] <= debug_cause_i;
        dcsr_q[1] <= (priv_mode_id_o == PRIV_LVL_M);
        if (csr_save_if_i) dpc_q <= pc_if_i;
        else if (csr_save_id_i) dpc_q <= pc_id_i;
        else dpc_q <= pc_wb_i;
      end
    end
  end

  assign csr_rdata_o = csr_rdata_int;
  assign illegal_csr_insn_o = illegal_csr & csr_access_i;
  assign csr_mtvec_o = mtvec_q;
  assign csr_mepc_o = mepc_q;
  assign csr_mtval_o = mtval_q;
  assign csr_depc_o = dpc_q;
  assign csr_shadow_err_o = 1'b0;
  assign double_fault_seen_o = 1'b0;

  assign data_ind_timing_o = DataIndTiming ? cpuctrlsts_q[1] : 1'b0;
  assign dummy_instr_en_o = DummyInstructions ? cpuctrlsts_q[2] : 1'b0;
  assign dummy_instr_mask_o = DummyInstructions ? cpuctrlsts_q[19:16] : 3'b0;
  assign dummy_instr_seed_en_o = 1'b0;
  assign dummy_instr_seed_o = '0;
  assign icache_enable_o = ICache ? cpuctrlsts_q[0] : 1'b0;
  assign debug_single_step_o = dcsr_q[2];
  assign debug_ebreakm_o = dcsr_q[15];
  assign debug_ebreaku_o = dcsr_q[12];
  assign trigger_match_o = 1'b0;

  always_comb begin
    mie_d = mie_q;
    mscratch_d = mscratch_q;
    mcountinhibit_d = mcountinhibit_q;
  end

  logic [63:0] mcycle_counter_val;
  assign mcycle_counter_val = mcycle_q;

  logic unused_signals;
  assign unused_signals = ^{
    csr_mtval_i, nmi_mode_i, pc_if_i, pc_id_i, pc_wb_i,
    ic_scr_key_valid_i, instr_ret_compressed_i,
    instr_ret_spec_i, instr_ret_compressed_spec_i,
    iside_wait_i, jump_i, branch_i, branch_taken_i,
    mem_load_i, mem_store_i, dside_wait_i, mul_wait_i, div_wait_i,
    debug_mode_entering_i, hart_id_i[31:1],
    CsrMvendorId, CsrMimpId
  };

endmodule

module ibex_if_stage #(
  parameter int unsigned DmHaltAddr = 32'h1A110800,
  parameter int unsigned DmExceptionAddr = 32'h1A110808,
  parameter bit DummyInstructions = 1'b0,
  parameter bit ICache = 1'b0,
  parameter ibex_pkg::rv32zc_e RV32ZC = ibex_pkg::RV32ZcaZcbZcmp,
  parameter bit ICacheECC = 1'b0,
  parameter bit ICacheTweakInfection = 1'b0,
  parameter int unsigned BusSizeECC = ibex_pkg::BUS_SIZE,
  parameter int unsigned TagSizeECC = ibex_pkg::IC_TAG_SIZE,
  parameter int unsigned LineSizeECC = ibex_pkg::IC_LINE_SIZE,
  parameter bit PCIncrCheck = 1'b0,
  parameter bit ResetAll = 1'b0,
  parameter ibex_pkg::lfsr_seed_t RndCnstLfsrSeed = ibex_pkg::RndCnstLfsrSeedDefault,
  parameter ibex_pkg::lfsr_perm_t RndCnstLfsrPerm = ibex_pkg::RndCnstLfsrPermDefault,
  parameter bit BranchPredictor = 1'b0,
  parameter bit MemECC = 1'b0,
  parameter int unsigned MemDataWidth = 32
) (
  input  logic                        clk_i,
  input  logic                        rst_ni,

  input  logic [31:0]                 boot_addr_i,
  input  logic                        req_i,

  output logic                        instr_req_o,
  output logic [31:0]                 instr_addr_o,
  input  logic                        instr_gnt_i,
  input  logic                        instr_rvalid_i,
  input  logic [MemDataWidth-1:0]     instr_rdata_i,
  input  logic                        instr_bus_err_i,
  output logic                        instr_intg_err_o,

  output logic [ibex_pkg::IC_NUM_WAYS-1:0] ic_tag_req_o,
  output logic                        ic_tag_write_o,
  output logic [ibex_pkg::IC_INDEX_W-1:0]  ic_tag_addr_o,
  output logic [TagSizeECC-1:0]       ic_tag_wdata_o,
  input  logic [TagSizeECC-1:0]       ic_tag_rdata_i [ibex_pkg::IC_NUM_WAYS],

  output logic [ibex_pkg::IC_NUM_WAYS-1:0] ic_data_req_o,
  output logic                        ic_data_write_o,
  output logic [ibex_pkg::IC_INDEX_W-1:0]  ic_data_addr_o,
  output logic [LineSizeECC-1:0]      ic_data_wdata_o,
  input  logic [LineSizeECC-1:0]      ic_data_rdata_i [ibex_pkg::IC_NUM_WAYS],
  input  logic                        ic_scr_key_valid_i,
  output logic                        ic_scr_key_req_o,

  output logic                        instr_valid_id_o,
  output logic                        instr_new_id_o,
  output logic [31:0]                 instr_rdata_id_o,
  output logic [31:0]                 instr_rdata_alu_id_o,
  output logic [15:0]                 instr_rdata_c_id_o,
  output logic                        instr_is_compressed_id_o,
  output ibex_pkg::instr_exp_e        instr_gets_expanded_id_o,
  output logic [15:0]                 instr_expanded_id_o,
  output logic                        instr_bp_taken_o,
  output logic                        instr_fetch_err_o,
  output logic                        instr_fetch_err_plus2_o,
  output logic                        illegal_c_insn_id_o,
  output logic                        dummy_instr_id_o,
  output logic [31:0]                 pc_if_o,
  output logic [31:0]                 pc_id_o,
  input  logic                        pmp_err_if_i,
  input  logic                        pmp_err_if_plus2_i,

  input  logic                        instr_valid_clear_i,
  input  logic                        pc_set_i,
  input  ibex_pkg::pc_sel_e           pc_mux_i,
  input  logic                        nt_branch_mispredict_i,
  input  ibex_pkg::exc_pc_sel_e       exc_pc_mux_i,
  input  ibex_pkg::exc_cause_t        exc_cause,
  input  logic                        dummy_instr_en_i,
  input  logic [2:0]                  dummy_instr_mask_i,
  input  logic                        dummy_instr_seed_en_i,
  input  logic [31:0]                 dummy_instr_seed_i,
  input  logic                        icache_enable_i,
  input  logic                        icache_inval_i,
  output logic                        icache_ecc_error_o,

  input  logic [31:0]                 branch_target_ex_i,
  input  logic [31:0]                 nt_branch_addr_i,

  input  logic [31:0]                 csr_mepc_i,
  input  logic [31:0]                 csr_depc_i,
  input  logic [31:0]                 csr_mtvec_i,
  output logic                        csr_mtvec_init_o,

  input  logic                        id_in_ready_i,
  output logic                        pc_mismatch_alert_o,
  output logic                        if_busy_o
);
  import ibex_pkg::*;

  logic [31:0] pc_if_q, pc_if_d;
  logic [31:0] pc_id_q;
  logic        fetch_valid;
  logic [31:0] fetch_rdata;
  logic        fetch_err;
  logic [31:0] exc_pc;
  logic        fetch_req;
  logic        if_id_pipe_reg_we;

  logic [31:0] instr_decompressed;
  logic        instr_is_compressed;
  logic        illegal_c_insn;

  logic        dummy_instr_req;
  logic [31:0] dummy_instr_instr;
  logic        dummy_instr_id_q;

  logic [31:0] prefetch_addr;

  ibex_compressed_decoder u_compressed_decoder (
    .instr_i         ({16'b0, fetch_rdata[15:0]}),
    .instr_o         (instr_decompressed),
    .is_compressed_o (instr_is_compressed),
    .illegal_instr_o (illegal_c_insn)
  );

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      pc_if_q <= ~32'b0;
    end else begin
      pc_if_q <= pc_if_d;
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      pc_id_q <= '0;
      dummy_instr_id_q <= 1'b0;
    end else if (if_id_pipe_reg_we) begin
      pc_id_q <= pc_if_q;
      dummy_instr_id_q <= dummy_instr_req;
    end
  end

  always_comb begin
    pc_if_d = pc_if_q;
    if (pc_set_i) begin
      unique case (pc_mux_i)
        PC_BOOT: pc_if_d = {boot_addr_i[31:2], 2'b00};
        PC_JUMP: pc_if_d = branch_target_ex_i;
        PC_EXC:  pc_if_d = exc_pc;
        PC_ERET: pc_if_d = csr_mepc_i & ~32'b1;
        PC_DRET: pc_if_d = csr_depc_i & ~32'b1;
        default: pc_if_d = {boot_addr_i[31:2], 2'b00};
      endcase
    end else if (fetch_valid && id_in_ready_i) begin
      if (instr_is_compressed)
        pc_if_d = pc_if_q + 32'd2;
      else
        pc_if_d = pc_if_q + 32'd4;
    end
  end

  always_comb begin
    exc_pc = csr_mtvec_i & ~32'b1;
    unique case (exc_pc_mux_i)
      EXC_PC_EXC:     exc_pc = csr_mtvec_i & ~32'b1;
      EXC_PC_IRQ:     exc_pc = csr_mtvec_i & ~32'b1;
      EXC_PC_DBD:     exc_pc = {DmHaltAddr[31:2], 2'b00};
      EXC_PC_DBG_EXC: exc_pc = {DmExceptionAddr[31:2], 2'b00};
      EXC_PC_DBG_TVA: exc_pc = csr_mtvec_i & ~32'b1;
      default:        exc_pc = csr_mtvec_i & ~32'b1;
    endcase
  end

  assign prefetch_addr = pc_if_d;

  assign fetch_req  = req_i & ~pmp_err_if_i;
  assign instr_req_o  = fetch_req;
  assign instr_addr_o = prefetch_addr;

  assign fetch_valid = instr_rvalid_i;
  assign fetch_rdata = instr_rdata_i[31:0];
  assign fetch_err   = instr_bus_err_i | pmp_err_if_i;

  assign instr_intg_err_o = 1'b0;

  assign if_id_pipe_reg_we = fetch_valid & id_in_ready_i & ~pc_set_i;
  assign instr_new_id_o = if_id_pipe_reg_we;

  assign instr_valid_id_o = fetch_valid | pc_set_i;
  assign pc_if_o = pc_if_q;
  assign pc_id_o = pc_id_q;

  assign instr_rdata_c_id_o = fetch_rdata[15:0];
  assign instr_is_compressed_id_o = instr_is_compressed;

  always_comb begin
    instr_rdata_id_o = instr_decompressed;
    instr_rdata_alu_id_o = instr_decompressed;
    if (dummy_instr_req) begin
      instr_rdata_id_o = dummy_instr_instr;
      instr_rdata_alu_id_o = dummy_instr_instr;
      instr_is_compressed_id_o = 1'b0;
      illegal_c_insn = 1'b0;
    end
  end

  assign instr_gets_expanded_id_o = INSTR_NOT_EXPANDED;
  assign instr_expanded_id_o = '0;
  assign instr_bp_taken_o = 1'b0;

  assign instr_fetch_err_o = fetch_err;
  assign instr_fetch_err_plus2_o = 1'b0;
  assign illegal_c_insn_id_o = illegal_c_insn;
  assign dummy_instr_id_o = dummy_instr_id_q;

  assign csr_mtvec_init_o = 1'b0;
  assign pc_mismatch_alert_o = 1'b0;
  assign if_busy_o = 1'b0;
  assign icache_ecc_error_o = 1'b0;

  ibex_dummy_instr #(
    .DummyInstructions(DummyInstructions),
    .RndCnstLfsrSeed(RndCnstLfsrSeed),
    .RndCnstLfsrPerm(RndCnstLfsrPerm)
  ) u_dummy_instr (
    .clk_i,
    .rst_ni,
    .dummy_instr_en_i,
    .dummy_instr_mask_i,
    .dummy_instr_seed_en_i,
    .dummy_instr_seed_i,
    .dummy_instr_req_o(dummy_instr_req),
    .dummy_instr_instr_o(dummy_instr_instr),
    .dummy_instr_id_o()
  );

  assign ic_tag_req_o = '0;
  assign ic_tag_write_o = 1'b0;
  assign ic_tag_addr_o = '0;
  assign ic_tag_wdata_o = '0;
  assign ic_data_req_o = '0;
  assign ic_data_write_o = 1'b0;
  assign ic_data_addr_o = '0;
  assign ic_data_wdata_o = '0;
  assign ic_scr_key_req_o = 1'b0;

endmodule

module ibex_id_stage #(
  parameter bit RV32E = 1'b0,
  parameter ibex_pkg::rv32m_e RV32M = ibex_pkg::RV32MFast,
  parameter ibex_pkg::rv32b_e RV32B = ibex_pkg::RV32BNone,
