arguments.content:
module ibex_id_stage #(
  parameter bit RV32E = 1'b0,
  parameter ibex_pkg::rv32m_e RV32M = ibex_pkg::RV32MFast,
  parameter ibex_pkg::rv32b_e RV32B = ibex_pkg::RV32BNone,
  parameter bit BranchTargetALU = 1'b0,
  parameter bit DataIndTiming = 1'b0,
  parameter bit WritebackStage = 1'b0,
  parameter bit BranchPredictor = 1'b0,
  parameter bit MemECC = 1'b0
) (
  input  logic                        clk_i,
  input  logic                        rst_ni,

  output logic                        ctrl_busy_o,
  output logic                        illegal_insn_o,

  input  logic                        instr_valid_i,
  input  logic [31:0]                 instr_rdata_i,
  input  logic [31:0]                 instr_rdata_alu_i,
  input  logic [15:0]                 instr_rdata_c_i,
  input  logic                        instr_is_compressed_i,
  input  logic                        instr_bp_taken_i,

  input  logic                        branch_decision_i,

  output logic                        instr_first_cycle_id_o,
  output logic                        instr_valid_clear_o,
  output logic                        id_in_ready_o,
  input  logic                        instr_exec_i,
  output logic                        instr_req_o,
  output logic                        pc_set_o,
  output ibex_pkg::pc_sel_e           pc_mux_o,
  output logic                        nt_branch_mispredict_o,
  output logic [31:0]                 nt_branch_addr_o,
  output ibex_pkg::exc_pc_sel_e       exc_pc_mux_o,
  output ibex_pkg::exc_cause_t        exc_cause_o,
  output logic                        icache_inval_o,

  input  logic                        instr_fetch_err_i,
  input  logic                        instr_fetch_err_plus2_i,
  input  logic                        illegal_c_insn_i,
  input  logic [31:0]                 pc_id_i,

  input  logic                        ex_valid_i,
  input  logic                        lsu_resp_valid_i,

  output ibex_pkg::alu_op_e           alu_operator_ex_o,
  output logic [31:0]                 alu_operand_a_ex_o,
  output logic [31:0]                 alu_operand_b_ex_o,

  output logic [33:0]                 imd_val_q_ex_o [2],
  input  logic [33:0]                 imd_val_d_ex_i [2],
  input  logic [1:0]                  imd_val_we_ex_i,

  output logic [31:0]                 bt_a_operand_o,
  output logic [31:0]                 bt_b_operand_o,

  output logic                        mult_en_ex_o,
  output logic                        div_en_ex_o,
  output logic                        mult_sel_ex_o,
  output logic                        div_sel_ex_o,
  output ibex_pkg::md_op_e            multdiv_operator_ex_o,
  output logic [1:0]                  multdiv_signed_mode_ex_o,
  output logic [31:0]                 multdiv_operand_a_ex_o,
  output logic [31:0]                 multdiv_operand_b_ex_o,
  output logic                        multdiv_ready_id_o,

  output logic                        csr_access_o,
  output ibex_pkg::csr_op_e           csr_op_o,
  output logic [11:0]                 csr_addr_o,
  output logic                        csr_op_en_o,
  output logic                        csr_save_if_o,
  output logic                        csr_save_id_o,
  output logic                        csr_save_wb_o,
  output logic                        csr_restore_mret_id_o,
  output logic                        csr_restore_dret_id_o,
  output logic                        csr_save_cause_o,
  output logic [31:0]                 csr_mtval_o,
  input  ibex_pkg::priv_lvl_e         priv_mode_i,
  input  logic                        csr_mstatus_tw_i,
  input  logic                        illegal_csr_insn_i,
  input  logic                        data_ind_timing_i,

  output logic                        lsu_req_o,
  output logic                        lsu_we_o,
  output logic [1:0]                  lsu_type_o,
  output logic                        lsu_sign_ext_o,
  output logic [31:0]                 lsu_wdata_o,
  input  logic                        lsu_req_done_i,

  input  logic                        lsu_addr_incr_req_i,
  input  logic [31:0]                 lsu_addr_last_i,

  input  logic                        lsu_load_err_i,
  input  logic                        lsu_load_resp_intg_err_i,
  input  logic                        lsu_store_err_i,
  input  logic                        lsu_store_resp_intg_err_i,

  output logic                        expecting_load_resp_o,
  output logic                        expecting_store_resp_o,

  input  logic                        csr_mstatus_mie_i,
  input  logic                        irq_pending_i,
  input  ibex_pkg::irqs_t             irqs_i,
  input  logic                        irq_nm_i,
  output logic                        nmi_mode_o,

  output logic                        debug_mode_o,
  output logic                        debug_mode_entering_o,
  output ibex_pkg::dbg_cause_e        debug_cause_o,
  output logic                        debug_csr_save_o,
  input  logic                        debug_req_i,
  input  logic                        debug_single_step_i,
  input  logic                        debug_ebreakm_i,
  input  logic                        debug_ebreaku_i,
  input  logic                        trigger_match_i,

  input  logic [31:0]                 result_ex_i,
  input  logic [31:0]                 csr_rdata_i,

  output logic [4:0]                  rf_raddr_a_o,
  input  logic [31:0]                 rf_rdata_a_i,
  output logic [4:0]                  rf_raddr_b_o,
  input  logic [31:0]                 rf_rdata_b_i,
  output logic                        rf_ren_a_o,
  output logic                        rf_ren_b_o,
  output logic [4:0]                  rf_waddr_id_o,
  output logic [31:0]                 rf_wdata_id_o,
  output logic                        rf_we_id_o,
  output logic                        rf_rd_a_wb_match_o,
  output logic                        rf_rd_b_wb_match_o,
  input  logic [4:0]                  rf_waddr_wb_i,
  input  logic [31:0]                 rf_wdata_fwd_wb_i,
  input  logic                        rf_write_wb_i,

  output logic                        en_wb_o,
  output ibex_pkg::wb_instr_type_e    instr_type_wb_o,
  output logic                        instr_perf_count_id_o,
  input  logic                        ready_wb_i,
  input  logic                        outstanding_load_wb_i,
  input  logic                        outstanding_store_wb_i,

  output logic                        perf_jump_o,
  output logic                        perf_branch_o,
  output logic                        perf_tbranch_o,
  output logic                        perf_dside_wait_o,
  output logic                        perf_mul_wait_o,
  output logic                        perf_div_wait_o,
  output logic                        instr_id_done_o
);
  import ibex_pkg::*;

  logic illegal_insn_dec, ebrk_insn, ecall_insn, mret_insn, dret_insn, wfi_insn;
  logic branch_dec, jump_dec;
  logic mult_en_dec, div_en_dec;
  md_op_e multdiv_operator_dec;
  logic [1:0] multdiv_signed_mode_dec;
  alu_op_e alu_operator_dec;
  logic [31:0] operand_a_dec, operand_b_dec;
  logic [4:0] rf_raddr_a_dec, rf_raddr_b_dec, rf_waddr_dec;
  logic rf_we_dec, rf_ren_a_dec, rf_ren_b_dec;
  logic csr_access_dec;
  csr_op_e csr_op_dec;
  logic lsu_req_dec, lsu_we_dec;
  logic [1:0] lsu_type_dec;
  logic lsu_sign_ext_dec;

  logic instr_executing;
  logic [31:0] rf_rdata_a_fwd, rf_rdata_b_fwd;

  ibex_decoder #(
    .RV32E(RV32E),
    .RV32M(RV32M),
    .RV32B(RV32B)
  ) u_decoder (
    .instr_rdata_i,
    .illegal_c_insn_i,
    .alu_operator_o (alu_operator_dec),
    .operand_a_o    (operand_a_dec),
    .operand_b_o    (operand_b_dec),
    .mult_en_o      (mult_en_dec),
    .div_en_o       (div_en_dec),
    .multdiv_operator_o (multdiv_operator_dec),
    .multdiv_signed_mode_o (multdiv_signed_mode_dec),
    .rf_raddr_a_o   (rf_raddr_a_dec),
    .rf_raddr_b_o   (rf_raddr_b_dec),
    .rf_waddr_o     (rf_waddr_dec),
    .rf_we_o        (rf_we_dec),
    .rf_ren_a_o     (rf_ren_a_dec),
    .rf_ren_b_o     (rf_ren_b_dec),
    .csr_access_o   (csr_access_dec),
    .csr_op_o       (csr_op_dec),
    .lsu_req_o      (lsu_req_dec),
    .lsu_we_o       (lsu_we_dec),
    .lsu_type_o     (lsu_type_dec),
    .lsu_sign_ext_o (lsu_sign_ext_dec),
    .branch_o       (branch_dec),
    .jump_o         (jump_dec),
    .illegal_insn_o (illegal_insn_dec),
    .ebrk_insn_o    (ebrk_insn),
    .ecall_insn_o   (ecall_insn),
    .mret_insn_o    (mret_insn),
    .dret_insn_o    (dret_insn),
    .wfi_insn_o     (wfi_insn)
  );

  assign instr_executing = instr_valid_i & instr_exec_i;
  assign instr_first_cycle_id_o = instr_executing;

  always_comb begin
    rf_rdata_a_fwd = rf_rdata_a_i;
    rf_rdata_b_fwd = rf_rdata_b_i;
    if (rf_write_wb_i && rf_waddr_wb_i != 5'b0) begin
      if (rf_ren_a_dec && rf_waddr_wb_i == rf_raddr_a_dec)
        rf_rdata_a_fwd = rf_wdata_fwd_wb_i;
      if (rf_ren_b_dec && rf_waddr_wb_i == rf_raddr_b_dec)
        rf_rdata_b_fwd = rf_wdata_fwd_wb_i;
    end
  end

  assign rf_rd_a_wb_match_o = (rf_raddr_a_dec == rf_waddr_wb_i) & rf_ren_a_dec;
  assign rf_rd_b_wb_match_o = (rf_raddr_b_dec == rf_waddr_wb_i) & rf_ren_b_dec;

  logic [31:0] alu_operand_a, alu_operand_b;
  always_comb begin
    alu_operand_a = operand_a_dec;
    alu_operand_b = operand_b_dec;

    unique case (instr_rdata_i[6:0])
      7'b0110111, 7'b0010111: begin
        alu_operand_a = '0;
      end
      7'b1101111: begin
        alu_operand_a = pc_id_i;
      end
      7'b1100111: begin
        alu_operand_a = rf_rdata_a_fwd;
      end
      7'b1100011: begin
        alu_operand_a = rf_rdata_a_fwd;
        alu_operand_b = rf_rdata_b_fwd;
      end
      7'b0000011, 7'b0100011: begin
        alu_operand_a = rf_rdata_a_fwd;
      end
      7'b0010011: begin
        alu_operand_a = rf_rdata_a_fwd;
      end
      7'b0110011: begin
        alu_operand_a = rf_rdata_a_fwd;
        alu_operand_b = rf_rdata_b_fwd;
      end
      7'b1110011: begin
        alu_operand_a = rf_rdata_a_fwd;
      end
      default: ;
    endcase
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      imd_val_q_ex_o[0] <= '0;
      imd_val_q_ex_o[1] <= '0;
    end else begin
      if (imd_val_we_ex_i[0]) imd_val_q_ex_o[0] <= imd_val_d_ex_i[0];
      if (imd_val_we_ex_i[1]) imd_val_q_ex_o[1] <= imd_val_d_ex_i[1];
    end
  end

  assign alu_operator_ex_o     = alu_operator_dec;
  assign alu_operand_a_ex_o    = alu_operand_a;
  assign alu_operand_b_ex_o    = alu_operand_b;

  assign mult_en_ex_o          = mult_en_dec & instr_executing;
  assign div_en_ex_o           = div_en_dec & instr_executing;
  assign mult_sel_ex_o         = mult_en_dec;
  assign div_sel_ex_o          = div_en_dec;
  assign multdiv_operator_ex_o = multdiv_operator_dec;
  assign multdiv_signed_mode_ex_o = multdiv_signed_mode_dec;
  assign multdiv_operand_a_ex_o = rf_rdata_a_fwd;
  assign multdiv_operand_b_ex_o = rf_rdata_b_fwd;
  assign multdiv_ready_id_o    = 1'b1;

  assign bt_a_operand_o = pc_id_i;
  assign bt_b_operand_o = operand_b_dec;

  assign rf_raddr_a_o = rf_raddr_a_dec;
  assign rf_raddr_b_o = rf_raddr_b_dec;
  assign rf_waddr_id_o = rf_waddr_dec;
  assign rf_ren_a_o = rf_ren_a_dec;
  assign rf_ren_b_o = rf_ren_b_dec;

  assign csr_access_o = csr_access_dec;
  assign csr_op_o     = csr_op_dec;
  assign csr_addr_o   = instr_rdata_i[31:20];

  assign lsu_req_o     = lsu_req_dec & instr_executing;
  assign lsu_we_o      = lsu_we_dec;
  assign lsu_type_o    = lsu_type_dec;
  assign lsu_sign_ext_o = lsu_sign_ext_dec;
  assign lsu_wdata_o   = rf_rdata_b_fwd;

  always_comb begin
    rf_we_id_o = rf_we_dec & instr_executing & ~(mult_en_dec | div_en_dec);
    rf_wdata_id_o = result_ex_i;
    if (csr_access_dec) begin
      rf_wdata_id_o = csr_rdata_i;
    end
  end

  assign csr_op_en_o = csr_access_dec & instr_executing;
  assign instr_req_o = 1'b1;

  logic ctrl_pc_set;
  pc_sel_e ctrl_pc_mux;
  exc_pc_sel_e ctrl_exc_pc_mux;
  exc_cause_t ctrl_exc_cause;
  logic ctrl_csr_save_if;
  logic ctrl_csr_save_id;
  logic ctrl_csr_save_wb;
  logic ctrl_csr_restore_mret;
  logic ctrl_csr_restore_dret;
  logic ctrl_csr_save_cause;
  logic [31:0] ctrl_csr_mtval;
  logic ctrl_instr_valid_clear;
  logic ctrl_illegal_insn;
  logic ctrl_nmi_mode;
  logic ctrl_debug_mode;
  logic ctrl_debug_mode_entering;
  dbg_cause_e ctrl_debug_cause;
  logic ctrl_debug_csr_save;
  logic ctrl_icache_inval;
  logic ctrl_en_wb;
  wb_instr_type_e ctrl_instr_type_wb;
  logic ctrl_instr_perf_count;
  logic ctrl_instr_id_done;
  logic ctrl_perf_jump;
  logic ctrl_perf_branch;
  logic ctrl_perf_tbranch;
  logic ctrl_perf_dside_wait;
  logic ctrl_perf_mul_wait;
  logic ctrl_perf_div_wait;

  ibex_controller #(
    .WritebackStage(WritebackStage),
    .BranchPredictor(BranchPredictor),
    .MemECC(MemECC)
  ) controller_i (
    .clk_i,
    .rst_ni,

    .fetch_valid_i        (instr_valid_i & instr_exec_i),
    .fetch_ready_i        (id_in_ready_o),

    .instr_rdata_i,
    .instr_is_compressed_i,
    .instr_fetch_err_i,
    .instr_fetch_err_plus2_i,
    .illegal_c_insn_i,
    .illegal_insn_i       (illegal_insn_dec | illegal_csr_insn_i),
    .ecall_insn_i,
    .ebrk_insn_i,
    .mret_insn_i,
    .dret_insn_i,
    .wfi_insn_i,
    .branch_i             (branch_dec),
    .branch_decision_i,
    .jump_i               (jump_dec),
    .csr_access_i         (csr_access_dec),
    .csr_addr_i           (instr_rdata_i[31:20]),

    .lsu_req_i            (lsu_req_dec & instr_executing),
    .lsu_we_i             (lsu_we_dec),
    .lsu_rvalid_i         (lsu_resp_valid_i),
    .lsu_load_err_i,
    .lsu_store_err_i,

    .ctrl_busy_o,
    .instr_valid_clear_o  (ctrl_instr_valid_clear),
    .pc_set_o             (ctrl_pc_set),
    .pc_mux_o             (ctrl_pc_mux),
    .exc_pc_mux_o         (ctrl_exc_pc_mux),
    .exc_cause_o          (ctrl_exc_cause),
    .csr_save_if_o        (ctrl_csr_save_if),
    .csr_save_id_o        (ctrl_csr_save_id),
    .csr_save_wb_o        (ctrl_csr_save_wb),
    .csr_restore_mret_id_o(ctrl_csr_restore_mret),
    .csr_restore_dret_id_o(ctrl_csr_restore_dret),
    .csr_save_cause_o     (ctrl_csr_save_cause),
    .csr_mtval_o          (ctrl_csr_mtval),

    .csr_mstatus_mie_i,
    .irq_pending_i,
    .irqs_i,
    .irq_nm_i,
    .nmi_mode_o           (ctrl_nmi_mode),
    .priv_mode_i,

    .debug_req_i,
    .debug_mode_i         (ctrl_debug_mode),
    .debug_mode_o,
    .debug_mode_entering_o(ctrl_debug_mode_entering),
    .debug_cause_o        (ctrl_debug_cause),
    .debug_csr_save_o     (ctrl_debug_csr_save),
    .debug_single_step_o  (),
    .debug_ebreakm_o      (),
    .debug_ebreaku_o      (),
    .trigger_match_o      (),

    .id_in_ready_o,
    .ex_valid_o           (),

    .rf_we_i              (rf_we_dec),
    .rf_waddr_i           (rf_waddr_dec),

    .perf_jump_o          (ctrl_perf_jump),
    .perf_branch_o        (ctrl_perf_branch),
    .perf_tbranch_o       (ctrl_perf_tbranch),
    .perf_dside_wait_o    (ctrl_perf_dside_wait),
    .perf_mul_wait_o      (ctrl_perf_mul_wait),
    .perf_div_wait_o      (ctrl_perf_div_wait),

    .icache_inval_o       (ctrl_icache_inval),

    .en_wb_o              (ctrl_en_wb),
    .instr_type_wb_o      (ctrl_instr_type_wb),

    .ready_wb_i,

    .instr_id_done_o      (ctrl_instr_id_done),

    .rvfi_flush_next_o    (),
    .id_exception_o       (ctrl_illegal_insn),
    .exc_req_d            (),
    .exc_req_lsu          (),
    .ebreak_into_debug    (),
    .irq_nm_int           ()
  );

  assign pc_set_o              = ctrl_pc_set;
  assign pc_mux_o              = ctrl_pc_mux;
  assign exc_pc_mux_o          = ctrl_exc_pc_mux;
  assign exc_cause_o           = ctrl_exc_cause;
  assign csr_save_if_o         = ctrl_csr_save_if;
  assign csr_save_id_o         = ctrl_csr_save_id;
  assign csr_save_wb_o         = ctrl_csr_save_wb;
  assign csr_restore_mret_id_o = ctrl_csr_restore_mret;
  assign csr_restore_dret_id_o = ctrl_csr_restore_dret;
  assign csr_save_cause_o      = ctrl_csr_save_cause;
  assign csr_mtval_o           = ctrl_csr_mtval;
  assign instr_valid_clear_o   = ctrl_instr_valid_clear;
  assign illegal_insn_o        = ctrl_illegal_insn;
  assign nmi_mode_o            = ctrl_nmi_mode;
  assign debug_mode_o          = ctrl_debug_mode;
  assign debug_mode_entering_o = ctrl_debug_mode_entering;
  assign debug_cause_o         = ctrl_debug_cause;
  assign debug_csr_save_o      = ctrl_debug_csr_save;
  assign icache_inval_o        = ctrl_icache_inval;
  assign en_wb_o               = ctrl_en_wb;
  assign instr_type_wb_o       = ctrl_instr_type_wb;
  assign instr_perf_count_id_o = ctrl_instr_perf_count;
  assign instr_id_done_o       = ctrl_instr_id_done;
  assign perf_jump_o           = ctrl_perf_jump;
  assign perf_branch_o         = ctrl_perf_branch;
  assign perf_tbranch_o        = ctrl_perf_tbranch;
  assign perf_dside_wait_o     = ctrl_perf_dside_wait;
  assign perf_mul_wait_o       = ctrl_perf_mul_wait;
  assign perf_div_wait_o       = ctrl_perf_div_wait;
  assign nt_branch_mispredict_o = 1'b0;
  assign nt_branch_addr_o      = '0;
  assign expecting_load_resp_o  = 1'b0;
  assign expecting_store_resp_o = 1'b0;

endmodule

module ibex_id_stage #(
  parameter bit RV32E = 1'b0,
  parameter ibex_pkg::rv32m_e RV32M = ibex_pkg::RV32MFast,
  parameter ibex_pkg::rv32b_e RV32B = ibex_pkg::RV32BNone,
  parameter bit BranchTargetALU = 1'b0,
  parameter bit DataIndTiming = 1'b0,
  parameter bit WritebackStage = 1'b0,
  parameter bit BranchPredictor = 1'b0,
  parameter bit MemECC = 1'b0
) (
  input  logic                        clk_i,
  input  logic                        rst_ni,

  output logic                        ctrl_busy_o,
  output logic                        illegal_insn_o,

  input  logic                        instr_valid_i,
  input  logic [31:0]                 instr_rdata_i,
  input  logic [31:0]                 instr_rdata_alu_i,
  input  logic [15:0]                 instr_rdata_c_i,
  input  logic                        instr_is_compressed_i,
  input  logic                        instr_bp_taken_i,

  input  logic                        branch_decision_i,

  output logic                        instr_first_cycle_id_o,
  output logic                        instr_valid_clear_o,
  output logic                        id_in_ready_o,
  input  logic                        instr_exec_i,
  output logic                        instr_req_o,
  output logic                        pc_set_o,
  output ibex_pkg::pc_sel_e           pc_mux_o,
  output logic                        nt_branch_mispredict_o,
  output logic [31:0]                 nt_branch_addr_o,
  output ibex_pkg::exc_pc_sel_e       exc_pc_mux_o,
  output ibex_pkg::exc_cause_t        exc_cause_o,
  output logic                        icache_inval_o,

  input  logic                        instr_fetch_err_i,
  input  logic                        instr_fetch_err_plus2_i,
  input  logic                        illegal_c_insn_i,
  input  logic [31:0]                 pc_id_i,

  input  logic                        ex_valid_i,
  input  logic                        lsu_resp_valid_i,

  output ibex_pkg::alu_op_e           alu_operator_ex_o,
  output logic [31:0]                 alu_operand_a_ex_o,
  output logic [31:0]                 alu_operand_b_ex_o,

  output logic [33:0]                 imd_val_q_ex_o [2],
  input  logic [33:0]                 imd_val_d_ex_i [2],
  input  logic [1:0]                  imd_val_we_ex_i,

  output logic [31:0]                 bt_a_operand_o,
  output logic [31:0]                 bt_b_operand_o,

  output logic                        mult_en_ex_o,
  output logic                        div_en_ex_o,
  output logic                        mult_sel_ex_o,
  output logic                        div_sel_ex_o,
  output ibex_pkg::md_op_e            multdiv_operator_ex_o,
  output logic [1:0]                  multdiv_signed_mode_ex_o,
  output logic [31:0]                 multdiv_operand_a_ex_o,
  output logic [31:0]                 multdiv_operand_b_ex_o,
  output logic                        multdiv_ready_id_o,

  output logic                        csr_access_o,
  output ibex_pkg::csr_op_e           csr_op_o,
  output logic [11:0]                 csr_addr_o,
  output logic                        csr_op_en_o,
  output logic                        csr_save_if_o,
  output logic                        csr_save_id_o,
  output logic                        csr_save_wb_o,
  output logic                        csr_restore_mret_id_o,
  output logic                        csr_restore_dret_id_o,
  output logic                        csr_save_cause_o,
  output logic [31:0]                 csr_mtval_o,
  input  ibex_pkg::priv_lvl_e         priv_mode_i,
  input  logic                        csr_mstatus_tw_i,
  input  logic                        illegal_csr_insn_i,
  input  logic                        data_ind_timing_i,

  output logic                        lsu_req_o,
  output logic                        lsu_we_o,
  output logic [1:0]                  lsu_type_o,
  output logic                        lsu_sign_ext_o,
  output logic [31:0]                 lsu_wdata_o,
  input  logic                        lsu_req_done_i,

  input  logic                        lsu_addr_incr_req_i,
  input  logic [31:0]                 lsu_addr_last_i,

  input  logic                        lsu_load_err_i,
  input  logic                        lsu_load_resp_intg_err_i,
  input  logic                        lsu_store_err_i,
  input  logic                        lsu_store_resp_intg_err_i,

  output logic                        expecting_load_resp_o,
  output logic                        expecting_store_resp_o,

  input  logic                        csr_mstatus_mie_i,
  input  logic                        irq_pending_i,
  input  ibex_pkg::irqs_t             irqs_i,
  input  logic                        irq_nm_i,
  output logic                        nmi_mode_o,

  output logic                        debug_mode_o,
  output logic                        debug_mode_entering_o,
  output ibex_pkg::dbg_cause_e        debug_cause_o,
  output logic                        debug_csr_save_o,
  input  logic                        debug_req_i,
  input  logic                        debug_single_step_i,
  input  logic                        debug_ebreakm_i,
  input  logic                        debug_ebreaku_i,
  input  logic                        trigger_match_i,

  input  logic [31:0]                 result_ex_i,
  input  logic [31:0]                 csr_rdata_i,

  output logic [4:0]                  rf_raddr_a_o,
  input  logic [31:0]                 rf_rdata_a_i,
  output logic [4:0]                  rf_raddr_b_o,
  input  logic [31:0]                 rf_rdata_b_i,
  output logic                        rf_ren_a_o,
  output logic                        rf_ren_b_o,
  output logic [4:0]                  rf_waddr_id_o,
  output logic [31:0]                 rf_wdata_id_o,
  output logic                        rf_we_id_o,
  output logic                        rf_rd_a_wb_match_o,
  output logic                        rf_rd_b_wb_match_o,
  input  logic [4:0]                  rf_waddr_wb_i,
  input  logic [31:0]                 rf_wdata_fwd_wb_i,
  input  logic                        rf_write_wb_i,

  output logic                        en_wb_o,
  output ibex_pkg::wb_instr_type_e    instr_type_wb_o,
  output logic                        instr_perf_count_id_o,
  input  logic                        ready_wb_i,
  input  logic                        outstanding_load_wb_i,
  input  logic                        outstanding_store_wb_i,

  output logic                        perf_jump_o,
  output logic                        perf_branch_o,
  output logic                        perf_tbranch_o,
  output logic                        perf_dside_wait_o,
  output logic                        perf_mul_wait_o,
  output logic                        perf_div_wait_o,
  output logic                        instr_id_done_o
);
  import ibex_pkg::*;

  logic illegal_insn_dec, ebrk_insn, ecall_insn, mret_insn, dret_insn, wfi_insn;
  logic branch_dec, jump_dec;
  logic mult_en_dec, div_en_dec;
  md_op_e multdiv_operator_dec;
  logic [1:0] multdiv_signed_mode_dec;
  alu_op_e alu_operator_dec;
  logic [31:0] operand_a_dec, operand_b_dec;
  logic [4:0] rf_raddr_a_dec, rf_raddr_b_dec, rf_waddr_dec;
  logic rf_we_dec, rf_ren_a_dec, rf_ren_b_dec;
  logic csr_access_dec;
  csr_op_e csr_op_dec;
  logic lsu_req_dec, lsu_we_dec;
  logic [1:0] lsu_type_dec;
  logic lsu_sign_ext_dec;

  logic instr_executing;
  logic [31:0] rf_rdata_a_fwd, rf_rdata_b_fwd;

  ibex_decoder #(
    .RV32E(RV32E),
    .RV32M(RV32M),
    .RV32B(RV32B)
  ) u_decoder (
    .instr_rdata_i,
    .illegal_c_insn_i,
    .alu_operator_o (alu_operator_dec),
    .operand_a_o    (operand_a_dec),
    .operand_b_o    (operand_b_dec),
    .mult_en_o      (mult_en_dec),
    .div_en_o       (div_en_dec),
    .multdiv_operator_o (multdiv_operator_dec),
    .multdiv_signed_mode_o (multdiv_signed_mode_dec),
    .rf_raddr_a_o   (rf_raddr_a_dec),
    .rf_raddr_b_o   (rf_raddr_b_dec),
    .rf_waddr_o     (rf_waddr_dec),
    .rf_we_o        (rf_we_dec),
    .rf_ren_a_o     (rf_ren_a_dec),
    .rf_ren_b_o     (rf_ren_b_dec),
    .csr_access_o   (csr_access_dec),
    .csr_op_o       (csr_op_dec),
    .lsu_req_o      (lsu_req_dec),
    .lsu_we_o       (lsu_we_dec),
    .lsu_type_o     (lsu_type_dec),
    .lsu_sign_ext_o (lsu_sign_ext_dec),
    .branch_o       (branch_dec),
    .jump_o         (jump_dec),
    .illegal_insn_o (illegal_insn_dec),
    .ebrk_insn_o    (ebrk_insn),
    .ecall_insn_o   (ecall_insn),
    .mret_insn_o    (mret_insn),
    .dret_insn_o    (dret_insn),
    .wfi_insn_o     (wfi_insn)
  );

  assign instr_executing = instr_valid_i & instr_exec_i;
  assign instr_first_cycle_id_o = instr_executing;

  always_comb begin
    rf_rdata_a_fwd = rf_rdata_a_i;
    rf_rdata_b_fwd = rf_rdata_b_i;
    if (rf_write_wb_i && rf_waddr_wb_i != 5'b0) begin
      if (rf_ren_a_dec && rf_waddr_wb_i == rf_raddr_a_dec)
        rf_rdata_a_fwd = rf_wdata_fwd_wb_i;
      if (rf_ren_b_dec && rf_waddr_wb_i == rf_raddr_b_dec)
        rf_rdata_b_fwd = rf_wdata_fwd_wb_i;
    end
  end

  assign rf_rd_a_wb_match_o = (rf_raddr_a_dec == rf_waddr_wb_i) & rf_ren_a_dec;
  assign rf_rd_b_wb_match_o = (rf_raddr_b_dec == rf_waddr_wb_i) & rf_ren_b_dec;

  logic [31:0] alu_operand_a, alu_operand_b;
  always_comb begin
    alu_operand_a = operand_a_dec;
    alu_operand_b = operand_b_dec;

    unique case (instr_rdata_i[6:0])
      7'b0110111, 7'b0010111: alu_operand_a = '0;
      7'b1101111: alu_operand_a = pc_id_i;
      7'b1100111: alu_operand_a = rf_rdata_a_fwd;
      7'b1100011: begin
        alu_operand_a = rf_rdata_a_fwd;
        alu_operand_b = rf_rdata_b_fwd;
      end
      7'b0000011, 7'b0100011: alu_operand_a = rf_rdata_a_fwd;
      7'b0010011: alu_operand_a = rf_rdata_a_fwd;
      7'b0110011: begin
        alu_operand_a = rf_rdata_a_fwd;
        alu_operand_b = rf_rdata_b_fwd;
      end
      7'b1110011: alu_operand_a = rf_rdata_a_fwd;
      default: ;
    endcase
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      imd_val_q_ex_o[0] <= '0;
      imd_val_q_ex_o[1] <= '0;
    end else begin
      if (imd_val_we_ex_i[0]) imd_val_q_ex_o[0] <= imd_val_d_ex_i[0];
      if (imd_val_we_ex_i[1]) imd_val_q_ex_o[1] <= imd_val_d_ex_i[1];
    end
  end

  assign alu_operator_ex_o     = alu_operator_dec;
  assign alu_operand_a_ex_o    = alu_operand_a;
  assign alu_operand_b_ex_o    = alu_operand_b;

  assign mult_en_ex_o          = mult_en_dec & instr_executing;
  assign div_en_ex_o           = div_en_dec & instr_executing;
  assign mult_sel_ex_o         = mult_en_dec;
  assign div_sel_ex_o          = div_en_dec;
  assign multdiv_operator_ex_o = multdiv_operator_dec;
  assign multdiv_signed_mode_ex_o = multdiv_signed_mode_dec;
  assign multdiv_operand_a_ex_o = rf_rdata_a_fwd;
  assign multdiv_operand_b_ex_o = rf_rdata_b_fwd;
  assign multdiv_ready_id_o    = 1'b1;

  assign bt_a_operand_o = pc_id_i;
  assign bt_b_operand_o = operand_b_dec;

  assign rf_raddr_a_o = rf_raddr_a_dec;
  assign rf_raddr_b_o = rf_raddr_b_dec;
  assign rf_waddr_id_o = rf_waddr_dec;
  assign rf_ren_a_o = rf_ren_a_dec;
  assign rf_ren_b_o = rf_ren_b_dec;

  assign csr_access_o = csr_access_dec;
  assign csr_op_o     = csr_op_dec;
  assign csr_addr_o   = instr_rdata_i[31:20];

  assign lsu_req_o     = lsu_req_dec & instr_executing;
  assign lsu_we_o      = lsu_we_dec;
  assign lsu_type_o    = lsu_type_dec;
  assign lsu_sign_ext_o = lsu_sign_ext_dec;
  assign lsu_wdata_o   = rf_rdata_b_fwd;

  always_comb begin
    rf_we_id_o = rf_we_dec & instr_executing & ~(mult_en_dec | div_en_dec);
    rf_wdata_id_o = result_ex_i;
    if (csr_access_dec) begin
      rf_wdata_id_o = csr_rdata_i;
    end
  end

  assign csr_op_en_o = csr_access_dec & instr_executing;
  assign instr_req_o = 1'b1;

  typedef enum logic [2:0] {
    IDLE, WAIT_EX, WAIT_LSU, IRQ_TAKEN
  } id_fsm_e;

  id_fsm_e id_fsm_cs, id_fsm_ns;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) id_fsm_cs <= IDLE;
    else         id_fsm_cs <= id_fsm_ns;
  end

  logic id_exception;
  logic exc_req_d;
  logic exc_req_lsu;
  logic ebreak_into_debug;
  logic rvfi_flush_next;
  logic irq_nm_int;

  assign irq_nm_int = irq_nm_i & ~nmi_mode_o & ~debug_mode_o;

  always_comb begin
    id_fsm_ns = id_fsm_cs;
    id_in_ready_o = 1'b1;
    instr_valid_clear_o = 1'b0;
    pc_set_o = 1'b0;
    pc_mux_o = PC_BOOT;
    exc_pc_mux_o = EXC_PC_EXC;
    exc_cause_o = '0;
    csr_save_if_o = 1'b0;
    csr_save_id_o = 1'b0;
    csr_save_wb_o = 1'b0;
    csr_restore_mret_id_o = 1'b0;
    csr_restore_dret_id_o = 1'b0;
    csr_save_cause_o = 1'b0;
    csr_mtval_o = '0;
    ctrl_busy_o = 1'b0;
    icache_inval_o = 1'b0;
    perf_jump_o = 1'b0;
    perf_branch_o = 1'b0;
    perf_tbranch_o = 1'b0;
    perf_dside_wait_o = 1'b0;
    perf_mul_wait_o = 1'b0;
    perf_div_wait_o = 1'b0;
    en_wb_o = 1'b0;
    instr_type_wb_o = WB_INSTR_OTHER;
    instr_perf_count_id_o = 1'b0;
    instr_id_done_o = 1'b0;
    illegal_insn_o = 1'b0;
    nmi_mode_o = 1'b0;
    debug_mode_o = 1'b0;
    debug_mode_entering_o = 1'b0;
    debug_cause_o = DBG_CAUSE_NONE;
    debug_csr_save_o = 1'b0;
    nt_branch_mispredict_o = 1'b0;
    nt_branch_addr_o = '0;
    expecting_load_resp_o = 1'b0;
    expecting_store_resp_o = 1'b0;
    id_exception = 1'b0;
    exc_req_d = 1'b0;
    exc_req_lsu = 1'b0;
    ebreak_into_debug = 1'b0;
    rvfi_flush_next = 1'b0;

    unique case (id_fsm_cs)
      IDLE: begin
        if (instr_valid_i && instr_exec_i) begin
          ctrl_busy_o = 1'b1;
          instr_perf_count_id_o = 1'b1;
          en_wb_o = 1'b1;

          if (instr_fetch_err_i) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_EXC;
            exc_pc_mux_o = EXC_PC_EXC;
            csr_save_id_o = 1'b1;
            csr_save_cause_o = 1'b1;
            exc_cause_o = EXC_CAUSE_INSN_ACCESS;
            csr_mtval_o = pc_id_i;
            instr_valid_clear_o = 1'b1;
            instr_id_done_o = 1'b1;
            id_exception = 1'b1;
            exc_req_d = 1'b1;
          end else if (illegal_insn_dec || illegal_csr_insn_i) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_EXC;
            exc_pc_mux_o = EXC_PC_EXC;
            csr_save_id_o = 1'b1;
            csr_save_cause_o = 1'b1;
            exc_cause_o = EXC_CAUSE_ILLEGAL_INSN;
            csr_mtval_o = pc_id_i;
            illegal_insn_o = 1'b1;
            instr_valid_clear_o = 1'b1;
            instr_id_done_o = 1'b1;
            id_exception = 1'b1;
            exc_req_d = 1'b1;
          end else if (ecall_insn) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_EXC;
            exc_pc_mux_o = EXC_PC_EXC;
            csr_save_id_o = 1'b1;
            csr_save_cause_o = 1'b1;
            exc_cause_o = EXC_CAUSE_ECALL_MMODE;
            csr_mtval_o = pc_id_i;
            instr_valid_clear_o = 1'b1;
            instr_id_done_o = 1'b1;
            id_exception = 1'b1;
            exc_req_d = 1'b1;
          end else if (ebrk_insn) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_EXC;
            exc_pc_mux_o = EXC_PC_DBD;
            csr_save_id_o = 1'b1;
            csr_save_cause_o = 1'b1;
            exc_cause_o = EXC_CAUSE_BREAKPOINT;
            csr_mtval_o = pc_id_i;
            instr_valid_clear_o = 1'b1;
            instr_id_done_o = 1'b1;
            id_exception = 1'b1;
            ebreak_into_debug = 1'b1;
          end else if (mret_insn) begin
            csr_restore_mret_id_o = 1'b1;
            pc_set_o = 1'b1;
            pc_mux_o = PC_ERET;
            perf_jump_o = 1'b1;
            instr_id_done_o = 1'b1;
          end else if (dret_insn) begin
            csr_restore_dret_id_o = 1'b1;
            pc_set_o = 1'b1;
            pc_mux_o = PC_DRET;
            instr_id_done_o = 1'b1;
          end else if (branch_dec) begin
            perf_branch_o = 1'b1;
            if (branch_decision_i) begin
              pc_set_o = 1'b1;
              pc_mux_o = PC_JUMP;
              perf_tbranch_o = 1'b1;
              perf_jump_o = 1'b1;
            end
            instr_id_done_o = 1'b1;
          end else if (jump_dec) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_JUMP;
            perf_jump_o = 1'b1;
            instr_id_done_o = 1'b1;
          end else if (lsu_req_dec) begin
            if (lsu_we_dec) instr_type_wb_o = WB_INSTR_STORE;
            else instr_type_wb_o = WB_INSTR_LOAD;
            if (lsu_req_done_i) begin
              id_fsm_ns = WAIT_LSU;
              id_in_ready_o = 1'b0;
              if (lsu_we_dec) expecting_store_resp_o = 1'b1;
              else expecting_load_resp_o = 1'b1;
            end else begin
              id_fsm_ns = WAIT_LSU;
              id_in_ready_o = 1'b0;
            end
          end else if (mult_en_dec || div_en_dec) begin
            if (mult_en_dec) instr_type_wb_o = WB_INSTR_MULT;
            else instr_type_wb_o = WB_INSTR_MULT;
            if (!ex_valid_i) begin
              id_fsm_ns = WAIT_EX;
              id_in_ready_o = 1'b0;
              if (div_en_dec) perf_div_wait_o = 1'b1;
              else perf_mul_wait_o = 1'b1;
            end else begin
              instr_id_done_o = 1'b1;
              rf_we_id_o = rf_we_dec;
              rf_wdata_id_o = result_ex_i;
            end
          end else begin
            instr_id_done_o = 1'b1;
          end

          if (lsu_load_err_i) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_EXC;
            exc_pc_mux_o = EXC_PC_EXC;
            csr_save_id_o = 1'b1;
            csr_save_cause_o = 1'b1;
            exc_cause_o = EXC_CAUSE_LOAD_ACCESS;
            csr_mtval_o = lsu_addr_last_i;
            instr_id_done_o = 1'b1;
            exc_req_lsu = 1'b1;
            id_exception = 1'b1;
          end
          if (lsu_store_err_i) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_EXC;
            exc_pc_mux_o = EXC_PC_EXC;
            csr_save_id_o = 1'b1;
            csr_save_cause_o = 1'b1;
            exc_cause_o = EXC_CAUSE_STORE_ACCESS;
            csr_mtval_o = lsu_addr_last_i;
            instr_id_done_o = 1'b1;
            exc_req_lsu = 1'b1;
            id_exception = 1'b1;
          end

          if (irq_pending_i & csr_mstatus_mie_i & ~nmi_mode_o & ~debug_mode_o) begin
            rvfi_flush_next = 1'b1;
          end
          if (irq_nm_i & ~nmi_mode_o & ~debug_mode_o) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_EXC;
            exc_pc_mux_o = EXC_PC_IRQ;
            csr_save_id_o = 1'b1;
            csr_save_cause_o = 1'b1;
            nmi_mode_o = 1'b1;
            exc_cause_o = EXC_CAUSE_IRQ_EXTERNAL_M;
            instr_id_done_o = 1'b1;
            rvfi_flush_next = 1'b1;
          end
          if (debug_req_i & ~debug_mode_o) begin
            pc_set_o = 1'b1;
            pc_mux_o = PC_EXC;
            exc_pc_mux_o = EXC_PC_DBD;
            csr_save_id_o = 1'b1;
            debug_csr_save_o = 1'b1;
            debug_cause_o = DBG_CAUSE_HALTREQ;
            debug_mode_o = 1'b1;
            debug_mode_entering_o = 1'b1;
            instr_id_done_o = 1'b1;
          end
        end else begin
          ctrl_busy_o = instr_valid_i;
        end
      end

      WAIT_EX: begin
        ctrl_busy_o = 1'b1;
        id_in_ready_o = 1'b0;
        perf_mul_wait_o = mult_en_dec;
        perf_div_wait_o = div_en_dec;
        if (ex_valid_i) begin
          id_fsm_ns = IDLE;
          id_in_ready_o = 1'b1;
          instr_id_done_o = 1'b1;
          rf_we_id_o = rf_we_dec;
          rf_wdata_id_o = result_ex_i;
        end
      end

      WAIT_LSU: begin
        ctrl_busy_o = 1'b1;
        id_in_ready_o = 1'b0;
        perf_dside_wait_o = 1'b1;
        if (lsu_we_dec) expecting_store_resp_o = 1'b1;
        else expecting_load_resp_o = 1'b1;
        if (lsu_resp_valid_i) begin
          id_fsm_ns = IDLE;
          id_in_ready_o = 1'b1;
          instr_id_done_o = 1'b1;
          if (~lsu_we_dec) begin
            rf_we_id_o = 1'b1;
            rf_wdata_id_o = result_ex_i;
          end
        end
        if (lsu_load_err_i) begin
          id_fsm_ns = IDLE;
          pc_set_o = 1'b1;
          pc_mux_o = PC_EXC;
          exc_pc_mux_o = EXC_PC_EXC;
          csr_save_id_o = 1'b1;
          csr_save_cause_o = 1'b1;
          exc_cause_o = EXC_CAUSE_LOAD_ACCESS;
          csr_mtval_o = lsu_addr_last_i;
          instr_id_done_o = 1'b1;
          exc_req_lsu = 1'b1;
          id_exception = 1'b1;
        end
        if (lsu_store_err_i) begin
          id_fsm_ns = IDLE;
          pc_set_o = 1'b1;
          pc_mux_o = PC_EXC;
          exc_pc_mux_o = EXC_PC_EXC;
          csr_save_id_o = 1'b1;
          csr_save_cause_o = 1'b1;
          exc_cause_o = EXC_CAUSE_STORE_ACCESS;
          csr_mtval_o = lsu_addr_last_i;
          instr_id_done_o = 1'b1;
          exc_req_lsu = 1'b1;
          id_exception = 1'b1;
        end
      end

      default: id_fsm_ns = IDLE;
    endcase
  end

  ibex_controller #(
    .WritebackStage(WritebackStage),
    .BranchPredictor(BranchPredictor),
    .MemECC(MemECC)
  ) controller_i (
    .clk_i,
    .rst_ni,
    .fetch_valid_i   (1'b0),
    .fetch_ready_i   (1'b0),
    .instr_rdata_i   (32'b0),
    .instr_is_compressed_i (1'b0),
    .instr_fetch_err_i      (1'b0),
    .instr_fetch_err_plus2_i(1'b0),
    .illegal_c_insn_i       (1'b0),
    .illegal_insn_i         (1'b0),
    .ecall_insn_i           (1'b0),
    .ebrk_insn_i            (1'b0),
    .mret_insn_i            (1'b0),
    .dret_insn_i            (1'b0),
    .wfi_insn_i             (1'b0),
    .branch_i               (1'b0),
    .branch_decision_i      (1'b0),
    .jump_i                 (1'b0),
    .csr_access_i           (1'b0),
    .csr_addr_i             (32'b0),
    .lsu_req_i              (1'b0),
    .lsu_we_i               (1'b0),
    .lsu_rvalid_i           (1'b0),
    .lsu_load_err_i         (1'b0),
    .lsu_store_err_i        (1'b0),
    .ctrl_busy_o            (),
    .instr_valid_clear_o    (),
    .pc_set_o               (),
    .pc_mux_o               (),
    .exc_pc_mux_o           (),
    .exc_cause_o            (),
    .csr_save_if_o          (),
    .csr_save_id_o          (),
    .csr_save_wb_o          (),
    .csr_restore_mret_id_o  (),
    .csr_restore_dret_id_o  (),
    .csr_save_cause_o       (),
    .csr_mtval_o            (),
    .csr_mstatus_mie_i      (1'b0),
    .irq_pending_i          (1'b0),
    .irqs_i                 ('0),
    .irq_nm_i               (1'b0),
    .nmi_mode_o             (),
    .priv_mode_i            (PRIV_LVL_M),
    .debug_req_i            (1'b0),
    .debug_mode_i           (1'b0),
    .debug_mode_o           (),
    .debug_mode_entering_o  (),
    .debug_cause_o          (),
    .debug_csr_save_o       (),
    .debug_single_step_o    (),
    .debug_ebreakm_o        (),
    .debug_ebreaku_o        (),
    .trigger_match_o        (),
    .id_in_ready_o          (),
    .ex_valid_o             (),
    .rf_we_i                (1'b0),
    .rf_waddr_i             (5'b0),
    .perf_jump_o            (),
    .perf_branch_o          (),
    .perf_tbranch_o         (),
    .perf_dside_wait_o      (),
    .perf_mul_wait_o        (),
    .perf_div_wait_o        (),
    .icache_inval_o         (),
    .en_wb_o                (),
    .instr_type_wb_o        (),
    .ready_wb_i             (1'b1),
    .instr_id_done_o        (),
    .rvfi_flush_next_o      (),
    .id_exception_o         (),
    .exc_req_d              (),
    .exc_req_lsu            (),
    .ebreak_into_debug      (),
    .irq_nm_int             ()
  );

endmodule

arguments.newString:
logic csr_access_dec;
csr_op_e csr_op_dec;
logic lsu_req_dec, lsu_we;
logic [1:0] lsu_type_dec;
