// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

// Simple simulation SoC wrapping Ibex core with memories and peripherals
//
// Memory map:
//   0x100000 - 0x1FFFFF : RAM (instructions + data, 256KB = 2^18 words)
//   0x020000 - 0x020FFF : SIM_CTRL (simulation control)
//   0x030000 - 0x030FFF : TIMER (RISC-V timer)

module ibex_simple_system #(
  parameter int unsigned RV32E = 0,
  parameter ibex_pkg::rv32m_e RV32M = ibex_pkg::RV32MFast,
  parameter ibex_pkg::rv32b_e RV32B = ibex_pkg::RV32BNone,
  parameter ibex_pkg::rv32zc_e RV32ZC = ibex_pkg::RV32ZcaZcbZcmp,
  parameter ibex_pkg::regfile_e RegFile = ibex_pkg::RegFileFF,
  parameter int unsigned ICache = 0,
  parameter int unsigned ICacheECC = 0,
  parameter int unsigned SecureIbex = 0,
  parameter int unsigned ICacheScramble = 0,
  parameter int unsigned BranchPredictor = 0,
  parameter int unsigned DbgTriggerEn = 0,
  parameter int unsigned PMPEnable = 0,
  parameter int unsigned PMPGranularity = 0,
  parameter int unsigned PMPNumRegions = 4,
  parameter int unsigned MHPMCounterNum = 0,
  parameter int unsigned MHPMCounterWidth = 40,
  parameter bit          ResetAll = 1'b0,
  parameter int unsigned BranchTargetALU = 0,
  parameter int unsigned WritebackStage = 0,
  parameter int unsigned INSTR_CYCLE_DELAY = 0,
  parameter logic [31:0] SRAMInitFile = 'x
) (
  input  logic        IO_CLK,
  input  logic        IO_RST_N,
  output logic        fetch_enable_o
);

  import ibex_pkg::*;

  /////////////////
  // Clock Divider
  /////////////////

  logic clk_sys;

  always_ff @(posedge IO_CLK or negedge IO_RST_N) begin
    if (!IO_RST_N)
      clk_sys <= 1'b0;
    else
      clk_sys <= ~clk_sys;
  end

  /////////////////////////
  // Bus signal declarations
  /////////////////////////

  logic        instr_req;
  logic [31:0] instr_addr;
  logic [31:0] instr_rdata;
  logic        instr_gnt;
  logic        instr_rvalid;
  logic        instr_err;

  logic        data_req;
  logic [31:0] data_addr;
  logic        data_we;
  logic [3:0]  data_be;
  logic [31:0] data_wdata;
  logic [31:0] data_rdata;
  logic        data_gnt;
  logic        data_rvalid;
  logic        data_err;

  logic        irq_timer;

  /////////////////////////
  // RVFI signal declarations
  /////////////////////////

`ifdef RVFI
  logic         rvfi_valid;
  logic [63:0]  rvfi_order;
  logic [31:0]  rvfi_insn;
  logic         rvfi_trap;
  logic         rvfi_halt;
  logic         rvfi_intr;
  logic [ 1:0]  rvfi_mode;
  logic [ 1:0]  rvfi_ixl;
  logic [ 4:0]  rvfi_rs1_addr;
  logic [ 4:0]  rvfi_rs2_addr;
  logic [ 4:0]  rvfi_rs3_addr;
  logic [31:0]  rvfi_rs1_rdata;
  logic [31:0]  rvfi_rs2_rdata;
  logic [31:0]  rvfi_rs3_rdata;
  logic [ 4:0]  rvfi_rd_addr;
  logic [31:0]  rvfi_rd_wdata;
  logic [31:0]  rvfi_pc_rdata;
  logic [31:0]  rvfi_pc_wdata;
  logic [31:0]  rvfi_mem_addr;
  logic [ 3:0]  rvfi_mem_rmask;
  logic [ 3:0]  rvfi_mem_wmask;
  logic [31:0]  rvfi_mem_rdata;
  logic [31:0]  rvfi_mem_wdata;
  logic [31:0]  rvfi_ext_pre_mip;
  logic [31:0]  rvfi_ext_post_mip;
  logic         rvfi_ext_nmi;
  logic         rvfi_ext_nmi_int;
  logic         rvfi_ext_debug_req;
  logic         rvfi_ext_debug_mode;
  logic         rvfi_ext_rf_wr_suppress;
  logic [63:0]  rvfi_ext_mcycle;
  logic [31:0]  rvfi_ext_mhpmcounters [10];
  logic [31:0]  rvfi_ext_mhpmcountersh [10];
  logic         rvfi_ext_ic_scr_key_valid;
  logic         rvfi_ext_irq_valid;
  logic         rvfi_ext_expanded_insn_valid;
  logic [15:0]  rvfi_ext_expanded_insn;
  logic         rvfi_ext_expanded_insn_last;
`endif

  /////////////////////////
  // Address decode
  /////////////////////////

  logic is_ram_data;
  logic is_sim_ctrl_data;
  logic is_timer_data;

  assign is_ram_data      = (data_addr[31:20] == 12'h001);
  assign is_sim_ctrl_data = (data_addr[31:12] == 20'h00020);
  assign is_timer_data    = (data_addr[31:12] == 20'h00030);

  /////////////////////////
  // RAM (256KB at 0x100000)
  /////////////////////////

  localparam int RAM_SIZE = 2**18;

  logic [17:0] ram_instr_rd_addr;
  logic [31:0] ram_instr_rdata;
  logic [31:0] ram_data_rdata;

  ibex_simple_system_ram #(
    .RAMSize(RAM_SIZE),
    .SRAMInitFile(SRAMInitFile)
  ) u_ram (
    .clk_i          (clk_sys),
    .wr_en_i        (data_req & data_we & is_ram_data),
    .wr_addr_i      (data_addr[19:2]),
    .wr_wdata_i     (data_wdata),
    .wr_be_i        (data_be),
    .instr_addr_i   (ram_instr_rd_addr),
    .instr_rdata_o  (ram_instr_rdata),
    .data_addr_i    (data_addr_q[19:2]),
    .data_rdata_o   (ram_data_rdata)
  );

  /////////////////////////
  // Instruction fetch interface
  /////////////////////////

  assign instr_gnt = instr_req;
  assign instr_err = 1'b0;

  logic        instr_req_q;
  logic [31:0] instr_addr_q;

  always_ff @(posedge clk_sys or negedge IO_RST_N) begin
    if (!IO_RST_N) begin
      instr_req_q  <= 1'b0;
      instr_addr_q <= 32'b0;
    end else begin
      instr_req_q  <= instr_req & instr_gnt;
      if (instr_req & instr_gnt)
        instr_addr_q <= instr_addr;
    end
  end

  if (INSTR_CYCLE_DELAY == 0) begin : gen_no_instr_delay
    assign instr_rvalid = instr_req_q;
    assign ram_instr_rd_addr = instr_addr_q[19:2];
  end else begin : gen_instr_delay
    logic [31:0] instr_delay_cnt;
    logic        instr_delay_cnt_rst;
    logic        instr_delay_done;
    logic [31:0] instr_addr_delay_q;

    assign instr_delay_done   = (instr_delay_cnt == INSTR_CYCLE_DELAY[31:0]);
    assign instr_delay_cnt_rst = instr_delay_done | ~instr_req;

    always_ff @(posedge clk_sys or negedge IO_RST_N) begin
      if (!IO_RST_N) begin
        instr_delay_cnt <= 32'b0;
      end else if (instr_delay_cnt_rst) begin
        instr_delay_cnt <= 32'b0;
      end else begin
        instr_delay_cnt <= instr_delay_cnt + 32'd1;
      end
    end

    always_ff @(posedge clk_sys or negedge IO_RST_N) begin
      if (!IO_RST_N) begin
        instr_addr_delay_q <= 32'b0;
      end else if (instr_req & instr_gnt) begin
        instr_addr_delay_q <= instr_addr;
      end
    end

    assign instr_rvalid = instr_delay_done & instr_req_q;
    assign ram_instr_rd_addr = instr_addr_delay_q[19:2];
  end

  assign instr_rdata = ram_instr_rdata;

  /////////////////////////
  // Data access interface
  /////////////////////////

  assign data_gnt = data_req;
  assign data_err = 1'b0;

  logic        data_req_q;
  logic [31:0] data_addr_q;

  always_ff @(posedge clk_sys or negedge IO_RST_N) begin
    if (!IO_RST_N) begin
      data_req_q  <= 1'b0;
      data_addr_q <= 32'b0;
    end else begin
      data_req_q  <= data_req & data_gnt;
      if (data_req & data_gnt)
        data_addr_q <= data_addr;
    end
  end

  assign data_rvalid = data_req_q;

  // Latched address qualifiers for read data mux
  logic is_ram_data_q;
  logic is_timer_data_q;

  always_ff @(posedge clk_sys or negedge IO_RST_N) begin
    if (!IO_RST_N) begin
      is_ram_data_q   <= 1'b0;
      is_timer_data_q <= 1'b0;
    end else if (data_req & data_gnt) begin
      is_ram_data_q   <= is_ram_data;
      is_timer_data_q <= is_timer_data;
    end
  end

  /////////////////////////
  // TIMER peripheral at 0x30000
  /////////////////////////

  localparam logic [31:0] TIMER_MTIME    = 32'h030000;
  localparam logic [31:0] TIMER_MTIMEH   = 32'h030004;
  localparam logic [31:0] TIMER_MTIMECMP = 32'h030008;
  localparam logic [31:0] TIMER_MTIMECMPH = 32'h03000C;

  logic [63:0] mtime;
  logic [63:0] mtimecmp;

  always_ff @(posedge clk_sys or negedge IO_RST_N) begin
    if (!IO_RST_N) begin
      mtime    <= 64'b0;
      mtimecmp <= 64'hFFFFFFFFFFFFFFFF;
    end else begin
      mtime <= mtime + 64'd1;
      if (data_req & data_we & is_timer_data) begin
        case (data_addr[3:2])
          2'd0: mtime[31:0]    <= data_wdata;
          2'd1: mtime[63:32]   <= data_wdata;
          2'd2: mtimecmp[31:0] <= data_wdata;
          2'd3: mtimecmp[63:32] <= data_wdata;
        endcase
      end
    end
  end

  assign irq_timer = (mtime >= mtimecmp);

  logic [31:0] timer_rdata;

  always_comb begin
    case (data_addr_q[3:2])
      2'd0: timer_rdata = mtime[31:0];
      2'd1: timer_rdata = mtime[63:32];
      2'd2: timer_rdata = mtimecmp[31:0];
      2'd3: timer_rdata = mtimecmp[63:32];
      default: timer_rdata = 32'b0;
    endcase
  end

  /////////////////////////
  // SIM_CTRL peripheral at 0x20000
  /////////////////////////

  localparam logic [31:0] SIM_CTRL_OUT  = 32'h020000;
  localparam logic [31:0] SIM_CTRL_CTRL = 32'h020008;

  always_ff @(posedge clk_sys or negedge IO_RST_N) begin
    if (!IO_RST_N) begin
    end else if (data_req & data_we & is_sim_ctrl_data) begin
      case (data_addr[15:0])
        16'h0000: $fwrite(32'h80000002, "%c", data_wdata[7:0]);
        16'h0008: begin
          if (data_wdata[0])
            $finish;
        end
        default: ;
      endcase
    end
  end

  /////////////////////////
  // Data read mux
  /////////////////////////

  always_comb begin
    data_rdata = 32'b0;
    if (is_ram_data_q)
      data_rdata = ram_data_rdata;
    else if (is_timer_data_q)
      data_rdata = timer_rdata;
  end

  /////////////////////////
  // Ibex core instantiation
  /////////////////////////

  ibex_top_tracing #(
    .RV32E(RV32E),
    .RV32M(RV32M),
    .RV32B(RV32B),
    .RV32ZC(RV32ZC),
