module ibex_simple_system_ram_inner #(
  parameter int RAMSize = 2**18,
  parameter logic [31:0] SRAMInitFile = 'x
) (
  input  logic        clk_i,
  input  logic        wr_en_i,
  input  logic [17:0] wr_addr_i,
  input  logic [31:0] wr_wdata_i,
  input  logic [3:0]  wr_be_i,
  input  logic [17:0] instr_addr_i,
  output logic [31:0] instr_rdata_o,
  input  logic [17:0] data_addr_i,
  output logic [31:0] data_rdata_o
);

  logic [31:0] ram [0:RAMSize-1];

  function automatic void simutil_memload(input string filename);
    $readmemh(filename, ram);
  endfunction
  export "DPI-C" function simutil_memload;

  function automatic int simutil_set_mem(input int index, input logic [311:0] val);
    if (index >= 0 && index < RAMSize) begin
      ram[index] = val[31:0];
      return 1;
    end
    return 0;
  endfunction
  export "DPI-C" function simutil_set_mem;

  function automatic int simutil_get_mem(input int index, output logic [311:0] val);
    val = '0;
    if (index >= 0 && index < RAMSize) begin
      val[31:0] = ram[index];
      return 1;
    end
    return 0;
  endfunction
  export "DPI-C" function simutil_get_mem;

  initial begin : ram_init
    if (SRAMInitFile !== 32'bx) begin
      $readmemh(SRAMInitFile, ram);
    end
  end

  assign instr_rdata_o = ram[instr_addr_i];
  assign data_rdata_o  = ram[data_addr_i];

  logic [31:0] wr_data_merged;
  assign wr_data_merged[ 7: 0] = wr_be_i[0] ? wr_wdata_i[ 7: 0] : ram[wr_addr_i][ 7: 0];
  assign wr_data_merged[15: 8] = wr_be_i[1] ? wr_wdata_i[15: 8] : ram[wr_addr_i][15: 8];
  assign wr_data_merged[23:16] = wr_be_i[2] ? wr_wdata_i[23:16] : ram[wr_addr_i][23:16];
  assign wr_data_merged[31:24] = wr_be_i[3] ? wr_wdata_i[31:24] : ram[wr_addr_i][31:24];

  always_ff @(posedge clk_i) begin
    if (wr_en_i) begin
      ram[wr_addr_i] <= wr_data_merged;
    end
  end

endmodule

